import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAV: [CaseTemplate] = [laundromatChangeBox, libraryReadingRoom, leagueTreasurer, formerRoommateKey, petSuppliesBag, clothingBinTheft, remoteJobAdvance, mallBanReturn, couponStack, schoolRunDwi, expiredTagFlee, kayakDockTheft, altereCheckMail, fuelCardMisuse, hotelRoomTrashed, weddingGiftBox, busPassingStopArm, gymLockerWallet, ediblesAtFestival, phantomLandlord, neighborBoardPost, campTableBurn]

    static let laundromatChangeBox = SmallCases.make(
        key: "story.laundromatChangeBox",
        category: .property,
        headlines: ["Laundromat Change Machine Emptied Twice in One Week", "Owner's Camera Shows Visitor With Pry Tool"],
        law: "misdLarceny",
        spec: "Stole $380 in coins belonging to {V}, a laundromat, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A laundromat's change machine was pried open and emptied of $380 on {DATE}, the second time that week. A camera showed {D} working at the coin door with a flat bar. {DL} says {D.he} was fixing the door at the owner's request.",
        state: [E(.video, 3, "Laundromat Camera", "{D} pries the coin door with a flat bar."), E(.document, 2, "Coin Log", "$380 short at the morning count.")],
        defense: [E(.statement, 1, "Repair", "{DL} says the owner asked {D.him} to fix the door.")],
        role: "Laundromat owner",
        exam: [.direct("How long have you owned the laundromat, and how does the change machine work?", "\"I've owned it for nine years. The machine takes bills and gives quarters, and the coin box inside is emptied by me on Monday and Thursday mornings.\""), .direct("What did your laundromat camera show that night?", "\"It shows {D} at the change machine with a flat bar, prying at the coin door. The face is clear, and the whole thing takes a couple of minutes.\""), .direct("How much money was missing from the machine?", "\"The morning count was $380 short. It was the second time that week the change machine had been opened and emptied.\""), .direct("Did you ask {D} to repair the coin door?", "\"Never. I have never asked {DL} to touch that machine, and I never hired anyone to work on it at night.\""), .direct("What had happened earlier that week?", "\"Someone had pried the coin door once already, on Tuesday night. I reported it and put a camera over the machine, and it was pried open again on Thursday.\""), .direct("How did you identify the defendant?", "\"I watched the footage the next morning. {D.He} stands at the machine for about twenty minutes with a flat bar, working at the coin door, and the face is clearly visible.\""), .cross("The face on the video is clear, isn't it?", "\"Yes, it is clear. I had no trouble seeing who it was, and I gave the footage to deputies.\""), .cross("The coin door was already damaged from earlier that week, wasn't it?", "\"It had been pried earlier in the week, yes. That is why I was careful about checking the machine.\""), .cross("Was anyone else in the laundromat at that hour?", "\"I do not think so. It was after closing, and the camera shows only {DL} at the machine.\""), .cross("Did you ever ask the defendant or anyone else to repair that door?", "\"No. I've always called a repair service. I have never given anyone permission to open that machine.\""), .cross("Did the defendant have a key or any role at the laundromat?", "\"No. {DL} was a customer, as far as I know, and I'd seen {DL} a few times washing clothes.\"")],
        theory: ("{D} emptied the change machine.", "A repair job."),
        allocution: "\"I took it. I'm sorry.\"",
        truths: ("{DL} had a bag of quarters in the car.", "The owner had texted {DL} to look at the door."),
        defendant: [.direct("Why were you at the change machine with a flat bar?", "\"The owner had asked me to look at the coin door. It had been damaged earlier, and I was trying to fix it.\""), .direct("Did you take any coins out of the machine?", "\"No. I never took a coin. I was working on the door, not on the money inside.\""), .direct("Why were you working at 2 a.m.?", "\"The owner is busy during the day, and the laundromat is empty at night. It was easier to work then.\""), .direct("How do you know the owner?", "\"I've done laundry there for years, and the owner and I have talked about repairs. I used to do handyman work.\""), .direct("What did the owner ask you to do?", "\"To look at the coin door because it had been damaged and wasn't closing properly. I got the message by text a few days earlier.\""), .direct("Why were you there at 2 a.m.?", "\"The owner said the laundromat is empty at night and that I could work without bothering customers. I thought it was a good time.\""), .cross("You had a bag of quarters in your car, didn't you?", "\"I did. They were mine, from my own laundry and some change I keep in the car.\""), .cross("The owner says no such request was ever made. Why believe you?", "\"I understood it as a request. The owner texted me to look at the door, and I took that as permission.\""), .cross("Why use a flat bar on a coin door that was already damaged?", "\"It is the tool you use on a stuck door. I was trying to open it, not rob it.\""), .cross("You pried the door with a flat bar at 2 a.m. How is that a repair?", "\"A flat bar is the tool you'd use to realign a bent coin door. I was working to get it to close.\""), .cross("The owner says you were never asked. Do you have the text?", "\"I thought I did, but my phone was replaced and it got lost. I know that doesn't help.\"")],
        openings: ("A laundromat's change machine was pried open and emptied of $380 for the second time that week. The camera shows {D} working at the coin door with a flat bar, and the owner never asked for any repair.", "{D} was fixing a damaged coin door at the owner's request and took no coins. The defense will show a text from the owner and a person with nothing to hide on camera."),
        closings: ("A flat bar, a coin door, a clear face on camera, and $380 gone by morning. The owner never asked for any repair, and quarters in {D}'s car tell the rest.", "The owner texted {D} to look at the door, and the camera shows a person fixing it with the right tool. The State asks you to assume a theft that nobody has proved."),
        timeline: [(-3, "The first break-in."), (0, "2 a.m.: {DL} works at the coin door."), (0, "8 a.m.: the owner counts $380 short.")],
        identified: "The laundromat camera.",
        mood: .indifferent,
        impact: "We lost a week of profit.")

    static let libraryReadingRoom = SmallCases.make(
        key: "story.libraryReadingRoom",
        category: .publicOrder,
        headlines: ["Library Patron Screams at Staff Over Printing Fees", "Deputy Called to Public Library"],
        law: "disorderly",
        spec: "Disturbed the peace by loud and abusive language in a public library, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} screamed at a librarian over a printing fee on {DATE} and refused to lower {D.his} voice. Patrons left the reading room. A deputy asked {D} to leave twice. {DL} says the fee was a mistake.",
        state: [E(.statement, 3, "Librarian", "{D} screamed at staff and refused two requests to leave."), E(.video, 2, "Library Camera", "{D} waves arms at the desk.")],
        defense: [E(.statement, 1, "Fee Mistake", "{DL} says the fee was a mistake.")],
        role: "Librarian",
        exam: [.direct("What happened at the library that day?", "\"{D} screamed at me at the desk about a printing fee and would not lower {D.his} voice. Patrons in the reading room started to leave.\""), .direct("How many times did the deputy ask {D} to leave?", "\"Twice. {DL} stayed through the first request, and left only after the deputy came back a second time.\""), .direct("What was the fee in question?", "\"The printing charge was $2. It was a small amount, but {D.he} was loud about it for several minutes.\""), .direct("Where did this happen and how busy was the library?", "\"At the circulation desk on the first floor, about three o'clock on a weekday. The reading room was about half full, mostly students.\""), .direct("How did the dispute begin?", "\"{D.He} brought a stack of pages to the printer and was charged two dollars at the desk. {D.He} said it should have been ten cents a page and started to raise {D.his} voice.\""), .direct("What did you do when the shouting continued?", "\"I asked {DL} to lower {D.his} voice, then called my supervisor. A deputy arrived and asked {DL} to leave twice.\""), .cross("The fee was wrong, wasn't it?", "\"The posted schedule says ten cents a page, so I understand why {D.he} was upset about two dollars.\""), .cross("{D} did not threaten you, did {D.he}?", "\"No. There were no threats. It was shouting and waving of arms, nothing more.\""), .cross("Had {D} been warned before about noise?", "\"I believe there was a warning the week before. I did not give it myself, so I rely on our records.\""), .cross("Was the printing fee the library charged correct?", "\"No. The posted schedule says ten cents a page, and the register charged $2. We gave {DL} a refund after the incident.\""), .cross("Did anyone complain to you about the defendant?", "\"A few patrons asked me what was going on. Two of them left the reading room, but nobody filed a complaint.\"")],
        theory: ("{D} disrupted a library.", "A fee dispute."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had been warned about noise the week before.", "The posted fee schedule listed printing at ten cents a page, not the $2 charged."),
        defendant: [.direct("Did you raise your voice at the desk?", "\"Yes, I raised my voice. I was upset that I was charged two dollars for what should have cost a few cents.\""), .direct("Why were you so upset about the fee?", "\"The posted fee schedule said ten cents a page. I felt I was being overcharged, and nobody would listen to me.\""), .direct("Did you hear the deputy ask you to leave?", "\"The second time I did. The first time I did not hear it over my own frustration.\""), .direct("Describe what you were printing and why.", "\"A set of forms for a job application. I printed fifteen pages and was charged two dollars, when the sign said ten cents a page.\""), .direct("What did you say at the desk?", "\"I asked why it cost so much. The clerk said that was the fee, and I got frustrated and said it was wrong.\""), .direct("How did you feel when the deputy asked you to leave?", "\"Embarrassed. I left the second time the deputy asked, and I apologized to the clerk before I went out.\""), .cross("You had been warned about noise the week before, hadn't you?", "\"Yes, I had. I should have remembered, and I should have handled this more calmly.\""), .cross("Patrons left the reading room because of you, didn't they?", "\"Some did, and I regret that. It was not my intent to disturb anyone.\""), .cross("You refused to lower your voice when the librarian asked, correct?", "\"I did, at first. I was angry, and I kept going when I should have stopped.\""), .cross("You had been warned about noise a week earlier. Why raise your voice again?", "\"I'd forgotten that warning. I was upset about the fee and I let it show.\""), .cross("Patrons left the room because of you. Isn't that a disruption?", "\"It may have been. I wasn't trying to bother anyone, but I understand why they left.\"")],
        openings: ("{D} screamed at a librarian over a printing fee, refused to lower {D.his} voice, and drove patrons out of the reading room. A deputy had to ask {D} twice to leave.", "The fee was posted at ten cents a page, and {D} was charged two dollars. The defense will show a customer who was wrongly billed and who raised {D.his} voice, not a disturbance."),
        closings: ("Shouting at the desk, patrons leaving, and two requests to leave. A previous warning about noise means {D} knew better than to do this in a library.", "A wrong fee, a frustrated patron, and a few minutes of raised voices. No threats were made, and nobody was hurt. This is an argument at a desk, not a crime."),
        timeline: [(0, "3 p.m.: the printing fee."), (0, "3:10 p.m.: the screaming."), (0, "3:25 p.m.: a deputy arrives.")],
        identified: "A librarian.",
        mood: .indifferent)

    static let leagueTreasurer = SmallCases.make(
        key: "story.leagueTreasurer",
        category: .whiteCollar,
        headlines: ["Little League Treasurer Accused of Pocketing Registration Fees", "Parents Notice Missing Uniform Money"],
        law: "embezzlement",
        spec: "Embezzled $2,900 entrusted to {D} by {V}, a youth baseball league, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, treasurer of a youth baseball league, collected registration fees all spring. In June the league's bank account was $2,900 short of the fees parents said they paid. Deposits stopped for six weeks. {DL} says the fees went to equipment and receipts were lost.",
        state: [E(.document, 3, "Bank Records", "$2,900 of registration fees never deposited."), E(.document, 2, "Parent Receipts", "Nineteen parents hold receipts signed by {D}.")],
        defense: [E(.statement, 1, "Equipment", "{DL} says the money bought equipment.")],
        role: "League president",
        exam: [.direct("Describe the league and how fees are collected for the jury.", "\"It's a youth baseball league with about ninety players. Parents pay registration in the spring, and our treasurer collects the fees and deposits them in the league account.\""), .direct("What did you discover about the league's finances in June?", "\"The bank account was $2,900 short of the registration fees that parents said they paid. Deposits had stopped about six weeks earlier.\""), .direct("Who collected those fees?", "\"{D}, our treasurer, collected registration fees all spring and signed the receipts. Nineteen parents hold receipts signed by {DL}.\""), .direct("What did the equipment records show?", "\"Equipment invoices came to about $700. That is a long way from the $2,900 that was never deposited.\""), .direct("How did you discover the shortage?", "\"In June, the account balance was far lower than the registration list suggested. I asked the bank for statements and saw that deposits stopped for six weeks.\""), .direct("What did the parents say?", "\"Nineteen parents held receipts signed by {DL}, and the amounts added up to $2,900 more than the bank showed.\""), .cross("{D} says the money went to equipment, doesn't {D.he}?", "\"Yes, that is the account. But the invoices show only $700, and {D.he} has not been able to show the rest.\""), .cross("{D} says some receipts were lost, doesn't {D.he}?", "\"Yes, but the parents kept their copies. The parents' receipts are how we know what was paid.\""), .cross("Did {D} work for free as treasurer?", "\"Yes, as a volunteer. That does not give anyone the right to keep the league's money.\""), .cross("Did the defendant ever tell you that deposits were being delayed?", "\"No. {D.He} said everything was fine whenever I asked, and I didn't ask for statements until June.\""), .cross("Did the league keep a second signer on the account?", "\"No. {D.He} was the only one with access, and we hadn't set up any review process.\"")],
        theory: ("{D} kept league fees.", "Equipment and lost receipts."),
        allocution: "\"I took it. I'm sorry.\"",
        truths: ("{DL}'s car payment was made from the cash.", "Equipment invoices show $700."),
        defendant: [.direct("Did you take the league's money?", "\"No. The money went to equipment for the teams. I bought bats, helmets, and bases with it.\""), .direct("Where are the receipts for those purchases?", "\"I lost them. I kept them in a folder, and it went missing around the end of the season.\""), .direct("Why did the deposits stop for six weeks?", "\"I got busy and behind. I held the cash for a while, and I planned to deposit it in a batch.\""), .direct("Walk us through how you came to be treasurer.", "\"I volunteered because no one else would. I had a child on a team, and I was told it would take about an hour a week.\""), .direct("How did you handle the cash?", "\"I kept it in a lockbox at home until I had time to deposit it. During spring I fell behind and the box got fuller.\""), .direct("What did you buy for the league?", "\"Bats, helmets, and a pitching machine for the older teams. I paid for them from the cash and kept the receipts in a folder.\""), .cross("The invoices show only $700 in equipment. Where did the other $2,200 go?", "\"It was mostly bats and gear. I do not have the paper for all of it, and I know that is a problem.\""), .cross("A car payment was made with cash around the same time, wasn't it?", "\"Yes, but it was a coincidence. I made my car payment from my own pay, and cash is cash.\""), .cross("You signed receipts to nineteen parents. Why not deposit those fees?", "\"I meant to. I fell behind, and then I was embarrassed to say it.\""), .cross("Only $700 of equipment invoices turned up. Where did the other $2,200 go?", "\"Some went to supplies I bought at stores with no invoice. I know I should have kept better records.\""), .cross("Nineteen parents hold receipts you signed, don't they?", "\"Yes. I signed every one. I did give those parents proof of payment, and I know I should have deposited that money right away.\""), .cross("You skipped deposits for six weeks in the middle of the season, didn't you?", "\"Yes. I fell behind and kept the cash until I could catch up. I was ashamed and told myself I would fix it before anyone looked.\"")],
        openings: ("A youth baseball league's account came up $2,900 short of the registration fees parents said they paid. Nineteen parents hold receipts signed by the treasurer, {D}, and deposits stopped for six weeks.", "The defense witnesses will explain that {D} volunteered as treasurer, bought equipment for the teams, and lost receipts, not money. Sloppy bookkeeping is not theft."),
        closings: ("Nineteen receipts, $2,900 never deposited, and invoices that explain only $700. The money was collected for children's baseball, and it went somewhere else.", "A volunteer treasurer lost some paperwork and fell behind on deposits. The State must prove {D} meant to steal, and sloppy record keeping does not prove that."),
        timeline: [(-60, "The spring registration begins."), (-45, "Deposits stop."), (0, "The president reviews the statements.")],
        identified: "Bank records and parent receipts.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "Kids sat out for gear we paid for.")

    static let formerRoommateKey = SmallCases.make(
        key: "story.formerRoommateKey",
        category: .family,
        headlines: ["Former Tenant Uses Old Key to Enter Apartment", "Landlord Says Locks Were Changed Twice"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} moved out of an apartment in May. On {DATE}, {V}, the current tenant, found {D} inside the apartment using a key. {V} had been told by the landlord the locks were changed. {DL} says {D.he} came for a box left behind.",
        state: [E(.statement, 3, "Tenant", "{V} found {D} inside the apartment."), E(.document, 2, "Landlord Notice", "A notice to {D} not to return after move-out.")],
        defense: [E(.statement, 1, "Left Box", "{DL} says {D.he} came for a box.")],
        role: "Current tenant",
        exam: [.direct("How are you connected to this apartment?", "\"I'm the current tenant. I moved in after {D} moved out in May, and the landlord told me the locks had been changed.\""), .direct("What happened on {DATE}?", "\"At about 10 a.m., I came home and found {D.him} inside my apartment. {D.He} had used a key to get in.\""), .direct("How did you react?", "\"I was startled and afraid. I stepped back out and called deputies at 10:20 while {D.he} stayed inside.\""), .direct("What did {D} say?", "\"{D.He} said {D.he} was there for a box that was left behind. {D.He} said {D.he} thought it would be okay.\""), .direct("Had the landlord told you anything?", "\"Yes. The landlord had told me {DL} was not to return after move-out, and that a notice had been mailed.\""), .direct("What did you see the defendant doing?", "\"Standing in the living room, looking through a closet. {D.He} had a key chain in hand.\""), .cross("Isn't it true you had been in contact with the defendant about the box?", "\"We exchanged a few texts about it. I didn't tell {D.him} to come on that morning, but I'd said it was fine to pick it up.\""), .cross("Did the defendant threaten you?", "\"No. {D.He} was apologetic and calm. {D.He} didn't raise a hand or voice.\""), .cross("Did the defendant take anything?", "\"No. {D.He} had not picked up the box yet and didn't take anything of mine.\""), .cross("Did you tell {D} the locks had been changed?", "\"I didn't. I assumed the landlord had told {DL}, and I don't know how the key still worked.\""), .cross("How long was the defendant inside?", "\"About ten or fifteen minutes before I got home. I can't say exactly.\"")],
        theory: ("{D} entered after notice.", "A forgotten box."),
        allocution: "\"I should have called first.\"",
        truths: ("The landlord had mailed {DL} two warnings.", "{V}'s own text said '{DL}, come get your box anytime this week.'"),
        defendant: [.direct("Why did you go to the apartment?", "\"I'd left a box behind when I moved out in May. {V} texted me to come get it anytime that week.\""), .direct("How did you get in?", "\"With my old key. It still worked, so I thought nothing was wrong.\""), .direct("Did you know about the notice?", "\"The landlord mailed warnings, but I don't recall reading them. I didn't think they applied to a box pickup.\""), .direct("What did you do when {V} came in?", "\"I explained right away that I was there for the box. I offered to leave and let {V} call the landlord.\""), .direct("Did you take anything?", "\"No. I was looking for the box in the closet, and I hadn't found it yet.\""), .direct("How are you coping with what happened?", "\"Embarrassed. I should have knocked or waited for {V} to be home, and I'm sorry I scared {V.him}.\""), .cross("The landlord told you not to return, didn't they?", "\"I think I was told that, but I was told to stay out unless I had permission. I believed I had it.\""), .cross("You used a key that was supposed to be inactive?", "\"It still worked, so I used it. I didn't know the locks were meant to be changed.\""), .cross("You didn't call {V} before entering?", "\"No. I figured {V} was at work. I should have called first.\""), .cross("You received two warnings by mail?", "\"I'm told so. I didn't open one of them, and I own that.\""), .cross("{V} was frightened when {V.he} found you?", "\"I could tell. I'm sorry about that, and I'd apologize again.\"")],
        openings: ("{D} moved out in May, and the landlord told {D} not to come back. On {DATE}, {V} came home to find {D} inside the apartment, using a key that should no longer have worked.", "{D} had been told by text to come pick up a box that week and used an old key that still worked. The defense says {D} believed the entry was permitted."),
        closings: ("A notice mailed to {D}, two warnings, and a key used at 10 a.m. to walk into a home that belonged to {V}. {D} knew the rule and entered anyway.", "{V}'s own text invited {D} to come get the box, and {D} was open, calm, and apologetic. A person invited to pick up a box is not breaking into a home."),
        timeline: [(-30, "The landlord mails a notice."), (0, "10 a.m.: {DL} enters with a key."), (0, "10:20 a.m.: {V} calls deputies.")],
        identified: "The current tenant.",
        mood: .indifferent)

    static let petSuppliesBag = SmallCases.make(
        key: "story.petSuppliesBag",
        category: .property,
        headlines: ["Pet Store Loses $240 in Dog Supplies to Walkout", "Employee Saw Shopper Fill Duffel"],
        law: "larcenyMerchant",
        spec: "Took dog food and supplies valued at $240 from {V}, a pet store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "An employee at a pet store watched {D} fill a duffel with dog food and supplies on {DATE} and walk out. The goods were worth $240. {DL} says {D.he} paid at the register in a separate trip.",
        state: [E(.video, 3, "Store Camera", "{D} fills a duffel and leaves."), E(.document, 2, "Register Tape", "No sale rung for these items.")],
        defense: [E(.statement, 1, "Paid", "{DL} says {D.he} paid in a separate trip.")],
        role: "Pet store employee",
        exam: [.direct("What did you see in the store that afternoon?", "\"I watched {D} fill a duffel bag with dog food and other pet supplies, then walk toward the exit without stopping at a register.\""), .direct("What was the value of what was in the bag?", "\"About $240 in dog food and supplies. We totaled it from the shelf tags afterward.\""), .direct("What does the register tape show?", "\"There is no sale rung for those items at any time that day. Nothing matching that bag was paid for.\""), .direct("Where were you working in the store, and what did you notice?", "\"I was stocking the dog food aisle. A customer with an empty duffel walked in and started loading bags of food, treats, and a few toys.\""), .direct("How much time did {D} spend in the aisle?", "\"About fifteen minutes, as far as I could see. {D.He} went through the whole aisle and then walked out the front door past the registers.\""), .direct("What did you do?", "\"I called out, but {D.he} kept walking and got into a car. I called the manager, who checked the camera and the register tape.\""), .cross("{D} says there was a separate trip to pay, doesn't {D.he}?", "\"That is what {D.he} says. I do not see a sale for these items in our records.\""), .cross("Did {D} have any receipt?", "\"There was a receipt for a small purchase of dog treats, but it was not for what was in the duffel.\""), .cross("Was the duffel empty when the defendant came in?", "\"I believe so. I did not see it come in, but it looked empty on the camera at first.\""), .cross("Did you stop the defendant at the door?", "\"No. Our policy is not to physically stop anyone, and I'm not allowed to.\""), .cross("Could the defendant have paid earlier at another register?", "\"I don't think so. The register tape shows no sale for those items, but I can only speak to the register I could see.\"")],
        theory: ("{D} took pet supplies.", "A paid purchase."),
        allocution: "\"I'm sorry.\"",
        truths: ("The duffel was empty when {DL} entered.", "A separate receipt in {DL}'s wallet shows a purchase of dog treats at 3:50 p.m."),
        defendant: [.direct("Did you take those items without paying?", "\"No. I paid for what I bought. I made a separate trip to the register, and I had a receipt.\""), .direct("Why did you have a duffel bag in the store?", "\"I was carrying it for a trip. I use it for all kinds of things, and I walked in with it.\""), .direct("Where is your receipt for the items?", "\"I lost it. I had one for the dog treats, but I cannot find the rest.\""), .direct("Tell us about the duffel.", "\"It's the bag I carry for my dog's supplies when I travel. It was empty when I walked in.\""), .direct("What did you buy that day?", "\"Dog treats at about ten to four, before I went back to the aisle for food. I paid for them at the register.\""), .direct("What did you do when the employee called out?", "\"I didn't hear anything. I was on the phone, and I walked out and drove away.\""), .cross("The register tape shows no sale for those items, doesn't it?", "\"It may not, but I did pay. Maybe it was rung under a different code.\""), .cross("You walked out with a full duffel. Why not use a cart or a bag from the store?", "\"The duffel was already with me. I did not think about how it would look.\""), .cross("The time on your receipt is 3:50 p.m. How does that cover $240 in goods?", "\"It covers the treats. I paid for the rest on another trip that the tape may have missed.\""), .cross("You walked out with a full bag and no receipt. How do you explain that?", "\"I thought I'd paid, since I'd already rung up the treats. I didn't pay for the food and supplies, and I should have checked.\""), .cross("The register tape shows only one purchase, the treats. How is that a second purchase?", "\"It isn't. I paid for the treats, and I assumed the rest was part of the same trip.\"")],
        openings: ("An employee at a pet store watched {D} fill a duffel with dog food and supplies worth $240 and walk out. The register tape shows no sale for those items.", "The defense case is that {D} paid for what {D.he} bought, on a separate trip, and that a store receipt for dog treats shows an honest customer."),
        closings: ("A duffel filled in an aisle, $240 in goods, and no sale on the register tape. A receipt for a few dog treats does not cover a bag full of supplies.", "A receipt in {D}'s wallet shows a purchase, and the register tape may miss a separate trip. The State has to prove nothing was paid, and a gap in a tape does not do that."),
        timeline: [(0, "4:05 p.m.: {DL} enters with an empty duffel."), (0, "4:20 p.m.: the duffel is full."), (0, "4:22 p.m.: {DL} leaves.")],
        identified: "A store camera.",
        mood: .indifferent)

    static let clothingBinTheft = SmallCases.make(
        key: "story.clothingBinTheft",
        category: .property,
        headlines: ["Donation Bin Emptied by Driver With a Van", "Charity Says Weekly Donations Disappeared"],
        law: "misdLarceny",
        spec: "Stole donated clothing valued at $700 belonging to {V}, a charity, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A charity's clothing donation bin was emptied by someone with a van on {DATE}, taking about $700 in donated clothing. The charity's camera showed {D}'s van. {DL} says {D.he} thought the bin was abandoned.",
        state: [E(.video, 3, "Lot Camera", "{D}'s van backs to the bin and loads bags."), E(.document, 2, "Pickup Log", "The bin was due for pickup at noon.")],
        defense: [E(.statement, 1, "Abandoned", "{DL} says {D.he} thought the bin was abandoned.")],
        role: "Charity coordinator",
        exam: [.direct("What is your job at the charity?", "\"I'm the coordinator. I manage the donation bins, schedule pickups, and keep track of what comes in.\""), .direct("What happened on {DATE}?", "\"A clothing donation bin was emptied by someone with a van. About $700 in donated clothing was taken.\""), .direct("What does the lot camera show?", "\"At about 9 a.m. {D}'s van backs up to the bin and, by 9:10, bags are being loaded into the van.\""), .direct("When was the bin due for pickup?", "\"Noon that day. Our driver would have emptied it, and the clothes would have gone to our shelter.\""), .direct("How was the loss discovered?", "\"Our driver arrived at noon and found the bin empty. I reviewed the camera and called deputies.\""), .direct("What happened to the clothes?", "\"The next day, a listing of the same clothes appeared online. We recognized the brands and bags.\""), .cross("Isn't it true the bin was overflowing that week?", "\"It was quite full by the end of the week. We had a pickup scheduled for that day.\""), .cross("Was there a sign on the bin?", "\"I believe there was something taped to it, but I can't remember what it said.\""), .cross("Did {D} try to hide the van?", "\"No. It was parked in the open, and the camera shows the plate.\""), .cross("Did you see the defendant take the bags?", "\"I saw it on camera. I wasn't at the lot that morning.\""), .cross("Do abandoned bins exist in the area?", "\"Yes, a few. Ours is clearly marked with the charity's name and logo.\"")],
        theory: ("{D} took donated clothing.", "A mistake about an abandoned bin."),
        allocution: "\"I sold them. I'm sorry.\"",
        truths: ("The clothes were listed for sale online.", "The bin had been overflowing for days with a sign reading 'FULL: do not use'."),
        defendant: [.direct("Why did you load clothes from that bin?", "\"It looked abandoned to me. It was overflowing, and a sign on it said Full, do not use.\""), .direct("What did you think the sign meant?", "\"That the bin was no longer in service. I thought the clothes would be thrown out.\""), .direct("Did you know it belonged to a charity?", "\"I saw a logo, but I didn't read it. I assumed it was left over from some past drive.\""), .direct("What did you plan to do with the clothes?", "\"I planned to sell them. I thought they were being thrown out, so I took them to resell.\""), .direct("Why did you list them online?", "\"I wanted to sell them quickly. I didn't realize how wrong it was until deputies called.\""), .direct("How has this affected you?", "\"Embarrassed. I'd return all of it if I could, and I'd apologize to the charity.\""), .cross("The bin was due for pickup at noon, wasn't it?", "\"I didn't know that. If I had, I wouldn't have taken the bags.\""), .cross("You loaded bags into a van in broad daylight?", "\"Yes. I wasn't hiding, and I didn't think I was stealing.\""), .cross("You posted the clothes online the next day?", "\"I did, with brand names. That's how the charity found them.\""), .cross("The logo was on the bin?", "\"I saw it, but I didn't read it closely. I know I own that.\""), .cross("You didn't ask anyone before taking the clothes?", "\"No, because it seemed abandoned. I should have called the number on the bin.\"")],
        openings: ("On {DATE}, {D}'s van backed up to a charity's clothing bin and loaded bags for ten minutes. About $700 in donated clothing was taken, and the next day it was listed for sale online.", "{D} saw an overflowing bin with a sign reading Full, do not use, and thought it was abandoned. The defense says an honest mistake about ownership is not theft."),
        closings: ("The camera shows the van, the bags, and the time, and the clothes were for sale the next day. The bin was marked with the charity's logo and was due for pickup at noon.", "The bin was overflowing, a sign said it was full and not to use it, and {D} acted in daylight with the van's plate in full view. Believing something was abandoned is not stealing."),
        timeline: [(0, "9 a.m.: {DL}'s van backs to the bin."), (0, "9:10 a.m.: bags are loaded."), (1, "{DL} lists clothing online.")],
        identified: "A charity lot camera.",
        mood: .wantsConviction)

    static let remoteJobAdvance = SmallCases.make(
        key: "story.remoteJobAdvance",
        category: .whiteCollar,
        headlines: ["Job Seekers Pay 'Training Fees' for Remote Work That Never Starts", "Hiring Site Shows Same Contact Repeatedly"],
        law: "falsePretenses",
        spec: "Obtained $450 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} paid {D} a $450 'training fee' on {DATE} for a remote customer-service job. No job or training followed, and {D} stopped answering. Three other applicants paid the same fee. {DL} says the company folded before work began.",
        state: [E(.digital, 3, "Messages", "{D} asks for a $450 training fee before the first shift."), E(.document, 2, "Payment Record", "$450 sent to {D}'s account.")],
        defense: [E(.statement, 1, "Company Folded", "{DL} says the company folded.")],
        role: "Applicant",
        exam: [.direct("What were you told about the job?", "\"I applied for a remote customer-service job and was told I had to pay a $450 training fee before my first shift.\""), .direct("What did you pay?", "\"I sent $450 to {D}'s account. The payment record shows it, and the messages show {DL} asking for it.\""), .direct("What happened after you paid?", "\"No job and no training ever followed. {D.He} stopped answering my messages, and I learned three other applicants paid the same fee.\""), .direct("How did you find the job?", "\"An ad on a job board for a remote customer-service role with flexible hours. I applied and got a reply the same day.\""), .direct("What did the messages from {D} say?", "\"A message said I'd been accepted, and I needed to pay a $450 training fee before my first shift. The company would reimburse it after two weeks.\""), .direct("What happened when you asked about the start date?", "\"{DL} said it would be the next Monday, then pushed it back twice. After a week {DL} stopped answering and I couldn't find a company website.\""), .cross("{D} says the company folded before work began, doesn't {D.he}?", "\"That is what {D.he} says. I was never told that, and I never heard the company had closed.\""), .cross("Did you check whether the job existed before you paid?", "\"I looked at the ad and the messages. I should have asked for more proof, and I know that now.\""), .cross("Did you see the company's name on any contract?", "\"I saw a name in the ad. I did not receive a contract before I sent the money.\""), .cross("Did you research the company before paying?", "\"I looked at the ad and the job board listing, which looked normal. I didn't find reviews, but I didn't find any warnings either.\""), .cross("How did you learn about the other applicants?", "\"Another applicant posted in a job forum that they had paid the same fee. I contacted that applicant and then two others.\"")],
        theory: ("{D} collected fees for a job that did not exist.", "A company that folded."),
        allocution: "\"I'll repay everyone.\"",
        truths: ("{DL} posted the same ad in four cities.", "A staffing firm confirmed {DL} had a contract to recruit for a call center that later lost its client."),
        defendant: [.direct("Did you take a fee from {V}?", "\"Yes, for training. It was a standard fee for the job, and I told {V.him} what it was for.\""), .direct("Was there a real job?", "\"Yes. I was recruiting for a call center, and I believed the positions were real.\""), .direct("What happened to the company?", "\"It lost its client before work began. I did not control that, and it hurt me too.\""), .direct("Tell the jury about your recruiting work.", "\"I recruit people for call centers that hire remote workers. I get paid per hire and I post ads on several job boards.\""), .direct("Why did you charge a training fee?", "\"The call center told me each new hire would pay for software training, and that the fee would be refunded. I passed that along.\""), .direct("What happened to the contract?", "\"The client pulled out two weeks before the start date. I told the applicants, or I thought I did, and I didn't know how to give the money back.\""), .cross("You posted the same ad in four cities, didn't you?", "\"Yes. I was growing the recruiting. I wanted to fill positions in several places.\""), .cross("Four applicants paid, and none got a job. How is that not fraud?", "\"I did not intend to cheat anyone. The work fell apart, and I should have refunded them.\""), .cross("You were not registered to recruit, were you?", "\"The registration was pending. I did not have it yet, and I know that looks bad.\""), .cross("You posted the same ad in four cities. Wasn't that a lot of applicants for one contract?", "\"The center said it needed over a hundred people. I wanted to fill every slot.\""), .cross("None of the four got a job, and none got their money back. Isn't that a scam?", "\"I didn't mean for it to be. I thought the contract would go through, and I'm trying to repay what I took.\"")],
        openings: ("{V} paid {D} a $450 training fee for a remote customer-service job that never existed. No work followed, {D} stopped answering, and three other applicants paid the same fee.", "Jurors will hear that {D} was recruiting for a call center that lost its client. A job that collapses is a business failure, not a scheme to cheat applicants."),
        closings: ("A $450 fee before the first shift, no job ever offered, and four applicants out of pocket. A real employer does not ask for money and then disappear.", "{D} was recruiting for a real contract that fell through. A failed business is not a crime, and the State must prove {D} planned from the start to take money and give nothing."),
        timeline: [(-10, "The ad is posted."), (-3, "{V} pays $450."), (0, "{V} finds three others who paid.")],
        identified: "Messages and payment records.",
        mood: .wantsConviction)

    static let mallBanReturn = SmallCases.make(
        key: "story.mallBanReturn",
        category: .publicOrder,
        headlines: ["Shopper Banned From Mall Returns to Food Court", "Security Gives Deputies Copy of Written Ban"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a shopping mall, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} was banned in writing from a shopping mall in March. On {DATE} mall security found {D} in the food court and called deputies. {DL} says the ban was for one year and {D.he} thought it had expired.",
        state: [E(.document, 3, "Ban Letter", "A written ban for one year signed by {D}."), E(.video, 2, "Mall Camera", "{D} walks into the food court.")],
        defense: [E(.statement, 1, "Expired", "{DL} says {D.he} thought the ban had expired.")],
        role: "Mall security manager",
        exam: [.direct("Was {D} banned from the mall?", "\"Yes. In March, {D} was banned in writing from the mall. The ban letter bears {D.his} signature.\""), .direct("How long did the ban last?", "\"One year. The letter gives an end date a year after the signing, so it had not expired.\""), .direct("What happened on {DATE}?", "\"Our security found {DL} in the food court and called deputies. The camera shows {DL} walking in through a side door.\""), .direct("How is a ban at your mall handled?", "\"A manager meets the person, explains the reason, and has them sign a written notice with an end date. A copy goes to the person and a copy stays in our file.\""), .direct("What did the defendant's ban letter say?", "\"It was a one-year ban signed in March, with an end date in March of the following year. The letter lists three examples of conduct that led to it.\""), .direct("How did you find out the defendant was back?", "\"A guard recognized {DL} on the camera in the food court. I confirmed the ban in our file and called deputies.\""), .cross("The ban may have expired in the defendant's mind, mightn't it?", "\"I cannot speak to that. The letter says a year, and it was still in force.\""), .cross("Was the defendant disruptive that day?", "\"No. {D.He} was not causing trouble. {D.He} was simply there.\""), .cross("Did {D} keep a copy of the letter?", "\"I believe so. I have not seen {D.his} copy, so I cannot say what it states.\""), .cross("Was the defendant causing any trouble that day?", "\"No. {D.He} was sitting at a table with a drink and had not caused any disturbance.\""), .cross("Did the guard approach the defendant before calling deputies?", "\"The guard watched for about ten minutes to confirm, then told {DL} about the ban. {DL} said it had ended.\"")],
        theory: ("{D} returned during a ban.", "A mistaken date."),
        allocution: "\"I should have checked.\"",
        truths: ("{DL} signed the letter with the end date.", "The copy of the ban letter {DL} kept read 'six months'."),
        defendant: [.direct("Did you know you were still banned?", "\"I thought it had ended. I remembered the ban being for six months, and by then I thought it had expired.\""), .direct("Why did you enter through the side door?", "\"It was closer to where I parked. I did not think of it as sneaking in.\""), .direct("Did you sign the ban letter?", "\"Yes, I signed it in March. I did not read it as carefully as I own that.\""), .direct("Walk us through what you remember about the day you signed the letter.", "\"A security manager gave me the paper and said I was banned for a while. I was upset and signed without reading the details.\""), .direct("How long did you think the ban would last?", "\"Six months. That's what the manager said, and it's what the copy I kept says.\""), .direct("What were you doing at the mall that day?", "\"I'd stopped for a meal after a doctor's appointment nearby. I came in through the side door and went to the food court.\""), .cross("The letter says one year, doesn't it?", "\"The one I have says six months. I may have misread it.\""), .cross("You signed it, so you knew the terms, didn't you?", "\"I signed it, but I did not memorize it. I remembered six months.\""), .cross("You were in the food court, a place you were banned from. Why go?", "\"I wanted a meal and I did not think it was a problem. I would not have come if I knew.\""), .cross("You signed a letter that says one year. Why do you rely on a six-month copy?", "\"The copy I have says six months. I can't explain the difference, and I have been honest about what I believed.\""), .cross("You didn't call to check whether the ban was over. Why not?", "\"It didn't occur to me. I thought enough time had passed.\"")],
        openings: ("{D} was banned in writing from a shopping mall in March for one year. On {DATE}, mall security found {D} in the food court and called deputies.", "The defense evidence will establish that {D} remembered a six-month ban, believed it had ended, and caused no trouble at all at the mall."),
        closings: ("A written ban, a signature, a one-year term, and {D} in the food court only months later. The letter is clear, and {D} signed it.", "{D} kept a copy that said six months and walked into a food court in good faith. A mistake about an end date is not defiance, and the State must prove {D} knew."),
        timeline: [(-240, "The ban letter is signed."), (0, "12:30 p.m.: {DL} enters the food court."), (0, "12:45 p.m.: deputies arrive.")],
        identified: "A signed ban letter.",
        mood: .indifferent,
        doctrines: ["mistakeOfFact"])

    static let couponStack = SmallCases.make(
        key: "story.couponStack",
        category: .whiteCollar,
        headlines: ["Shopper Uses Copied Coupons Across Three Stores", "Manufacturer Flags Duplicate Barcodes"],
        law: "falsePretenses",
        spec: "Obtained $1,350 in merchandise from {V}, a retailer, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} redeemed copied manufacturer coupons at three stores over two weeks, getting $1,350 in merchandise. The coupons carried identical barcodes. {DL} says the coupons came from a mailing and {D.he} did not know they were copies.",
        state: [E(.document, 3, "Coupon Redemptions", "Identical barcodes on 44 coupons."), E(.video, 2, "Register Camera", "{D} hands over a stack of coupons.")],
        defense: [E(.statement, 1, "Mailing", "{DL} says the coupons came in the mail.")],
        role: "Store loss-prevention officer",
        exam: [.direct("What did you notice about the coupons at your store?", "\"The coupons carried identical barcodes. That's a red flag, because each real manufacturer coupon should be unique. There were 44 of them in all.\""), .direct("What does the register camera show?", "\"{D} hands over a stack of coupons at the register, and the cashier scans them one after another. It shows the whole redemption.\""), .direct("What did {DL} get for those coupons?", "\"Over two weeks and three stores, {D.he} got $1,350 in merchandise. Each store saw the same pattern of coupons from the same source.\""), .direct("How do you check coupons at your store?", "\"The register scans the barcode and matches it against the manufacturer's list. A coupon that has been scanned before is flagged on the screen, and the cashier is supposed to call a manager.\""), .direct("How many coupons did {D} redeem at your store, and what did they cover?", "\"Nineteen at our store over four visits, covering pet food, razors, and diapers. The same barcode appeared on every one.\""), .direct("What did the manufacturer tell you?", "\"That the coupon was a real one but only valid for one use per household. The identical codes mean the coupons were reproduced rather than printed separately.\""), .cross("{DL} says the coupons came in the mail, doesn't {D.he}?", "\"Real coupons can come in the mail. But real mailed coupons don't carry identical barcodes in a stack of 44.\""), .cross("Can you tell who made the copies?", "\"No. I can tell the coupons were copies by the barcodes. Who made them is a different question, and I don't have that answer.\""), .cross("Did the cashiers accept the coupons without question?", "\"Yes, they scanned them. It wasn't until we compared barcodes that we noticed. A cashier wouldn't catch it at the counter.\""), .cross("Do real coupons ever carry the same barcode?", "\"Not within a mailing. A mass-distributed coupon would normally have a unique serial number, but I can't say how all of them are printed.\""), .cross("Did the defendant try to avoid scanning by splitting the stack across lanes?", "\"No. {D.He} used the same lane each time and handed over the stack at once. The cashier scanned them without trouble.\"")],
        theory: ("{D} used copied coupons.", "Coupons from a mailing."),
        allocution: "\"I'm sorry.\"",
        truths: ("A color printer with coupon files was in {DL}'s home.", "A newspaper insert that month carried the same coupon, and {DL} saved the inserts."),
        defendant: [.direct("Where did you get the coupons?", "\"They came in a mailing. I thought they were ordinary manufacturer coupons. I collect coupons and I never thought they were copies.\""), .direct("Did you know they were copies?", "\"No. I would never have used them if I did. They looked real to me, and the cashiers accepted them without any questions.\""), .direct("Why did you use so many coupons?", "\"I had a big stack and I used them as they came. I was trying to save money on groceries and household items.\""), .direct("Tell the jury where you got your coupons.", "\"They came in the mail in a plain envelope with a note that it was a thank-you offer. I'd also saved a few from newspaper inserts.\""), .direct("How did you use the coupons?", "\"I bought things I needed, mostly for my family, and used them as I went. I tried to stack a few for the best savings.\""), .direct("What did you think when the store called?", "\"I was stunned. I told them everything I knew, and I gave them the envelope the coupons came in.\""), .cross("44 coupons with identical barcodes, isn't that odd?", "\"It's odd now that you say it. I didn't compare them. I never looked at the barcodes. I just handed them over.\""), .cross("You used them at three different stores, didn't you?", "\"Yes, I shopped at several stores. I wasn't spreading them out to avoid detection. It was where I shop.\""), .cross("$1,350 is a lot in groceries and merchandise, isn't it?", "\"It is. I had several household needs. I thought the coupons were just a lucky run, and I didn't think about it.\""), .cross("Forty-four coupons with the same barcode at three stores. Didn't that strike you as odd?", "\"In hindsight, it does. I didn't look at the codes, and I never thought to check.\""), .cross("A color printer with coupon files was found at your home. How do you explain that?", "\"I use it for school projects and for my kids. I never printed coupons.\"")],
        openings: ("Over two weeks, {D} redeemed 44 coupons at three stores, all carrying identical barcodes, for $1,350 in merchandise. The State will show the camera, the redemption records, and the matching barcodes.", "The defense evidence includes a shopper who got a stack of coupons in the mail, used them openly, and never knew they were copies. A shopper is not a forger."),
        closings: ("Forty-four coupons with the same barcode, three stores, two weeks, and $1,350. Real coupons don't repeat like that, and {D} used every one.", "{D} used the coupons openly at the register and thought they came in the mail. The State has not proved {D} knew they were copies."),
        timeline: [(-14, "The first redemption."), (-7, "The second store."), (0, "The manufacturer flags the barcodes.")],
        identified: "Coupon redemption records.",
        mood: .wantsConviction)

    static let schoolRunDwi = SmallCases.make(
        key: "story.schoolRunDwi",
        category: .traffic,
        headlines: ["Parent Stopped at School Drop-Off With 0.09 Reading", "Teacher Smelled Alcohol at Car Window"],
        law: "dwi",
        spec: "Operated a vehicle on a street while subject to an impairing substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A teacher smelled alcohol on {D} at a school drop-off line at 7:40 a.m. on {DATE}. A deputy found {D} had a 0.09. {DL} says {D.he} used mouthwash and had a medical condition that affects breath tests.",
        state: [E(.forensic, 3, "Breath Test", "0.09 at the station."), E(.statement, 3, "Teacher", "Alcohol on {D}'s breath at the window.")],
        defense: [E(.statement, 1, "Mouthwash", "{DL} says mouthwash and a medical condition explain the reading.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you notice when you met {D}?", "\"A strong odor of alcohol and slow speech. A teacher at the school drop-off line had reported it at 7:40 that morning.\""), .direct("What did the breath test read?", "\"0.09 at the station on the instrument. That is over the legal limit of 0.08.\""), .direct("What did the teacher say?", "\"The teacher smelled alcohol on {D}'s breath at the car window. {D.He} was in the drop-off line with a child in the car.\""), .direct("Where did the encounter take place, and what time was it?", "\"In the school's drop-off line at about 7:40 a.m. A teacher at the curb called my office after smelling alcohol on a driver.\""), .direct("What did you see and smell when you met the defendant?", "\"A strong odor of alcohol coming from the car, glassy eyes, and slow speech. A child was in the back seat in a booster seat.\""), .direct("Where and when was the breath test given?", "\"At the station about fifty minutes later, on a machine that records the sample. It read 0.09, and the test was witnessed by a second officer.\""), .cross("{D} says mouthwash caused the odor, doesn't {D.he}?", "\"That is what {D.he} says. Mouthwash may leave an odor, but it does not produce a 0.09 on a breath test.\""), .cross("{D} said there is a medical condition that affects breath tests, didn't {D.he}?", "\"Yes, {D.he} said so. I have no record of that condition, so I could not verify it.\""), .cross("How was the instrument maintained?", "\"It is checked monthly. I rely on the technician for that, and I am not the one who services it.\""), .cross("Could the mouthwash produce a reading as high as 0.09?", "\"Mouthwash can cause a short-lived spike, but fifteen minutes of observation before the test normally removes it. I can't say how much remained.\""), .cross("Did you find an open container in the car?", "\"A bottle was in the console, but it was sealed and I did not test the contents.\"")],
        theory: ("{D} drove drunk with a child in the car.", "Mouthwash and a medical condition."),
        allocution: "\"I made a terrible choice.\"",
        truths: ("A bottle was in the console.", "The instrument had failed its monthly check two weeks earlier, a technician said."),
        defendant: [.direct("Had you been drinking that morning?", "\"No. I did not drink that morning. I had a late night the night before, but I was not drinking that day.\""), .direct("Why was there an odor?", "\"I used mouthwash before leaving. It has alcohol in it, and I can see how it would smell.\""), .direct("Tell us about your morning.", "\"I got up at six, got my child ready, and left at about 7:15. I rinsed with mouthwash before leaving because I'd had a bad taste in my mouth.\""), .direct("What medical condition do you have?", "\"A reflux condition that can leave alcohol vapors from certain medicines and foods in my mouth. My doctor told me it can affect breath tests.\""), .direct("What happened at the station?", "\"I blew into the machine twice. The first was invalid and I did it again, and the second read 0.09, which I was surprised to see.\""), .direct("What did you do to prepare for the breath test at the station?", "\"I told the deputy about my condition and the mouthwash. I rinsed with water and asked whether the machine had been tested recently, and the deputy did not know.\""), .cross("A reading of 0.09 is not from mouthwash, is it?", "\"I do not know. I only know what I did that morning, and I did not drink.\""), .cross("There was a bottle in your console, wasn't there?", "\"It was not mine. It may have been there from someone else.\""), .cross("You were driving a child in a school drop-off line, weren't you?", "\"Yes, and I would never put a child at risk. I felt fine and I believed I was fine.\""), .cross("You were driving a child to school. Why risk it with an odor of alcohol?", "\"I wasn't drinking. I'd used mouthwash and didn't think about how it would smell.\""), .cross("The bottle in your console. Whose was it?", "\"Not mine. It may have been left by someone who rode with me, and I didn't know it was there.\"")],
        openings: ("At 7:40 in the morning, a teacher smelled alcohol on {D} at a school drop-off line. A deputy found {D} had a 0.09 at the station, above the legal limit.", "The defense will present evidence that {D} used mouthwash, has a medical condition that affects breath tests, and had not been drinking that morning."),
        closings: ("A teacher smelled alcohol, the deputy saw slow speech, and the instrument read 0.09. All of this happened at a school drop-off line at 7:40 in the morning.", "Mouthwash, a medical condition, and an instrument that may have failed its own checks. The State's number cannot carry the whole case, and doubt remains."),
        timeline: [(0, "7:35 a.m.: the drop-off line."), (0, "7:40 a.m.: the teacher notices the odor."), (0, "8:30 a.m.: the breath test.")],
        identified: "A teacher and a breath test.",
        aggravating: [],
        mood: .wantsConviction)

    static let expiredTagFlee = SmallCases.make(
