        category: .traffic,
        headlines: ["Driver With Expired Tag Speeds Away, Ditches Car", "Deputy Finds Keys in Hedge"],
        law: "fleeing",
        spec: "Operated a motor vehicle on a highway while fleeing a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A deputy tried to stop a car with an expired tag on {DATE}. The car sped away and was abandoned in a cul-de-sac. {D} was found hiding behind a shed, and the car's keys were in a hedge. {DL} says someone else drove.",
        state: [E(.video, 3, "Dash Camera", "A car speeds away from lights."), E(.physical, 2, "Keys", "Keys in a hedge beside the car.", .search)],
        defense: [E(.statement, 1, "Someone Else", "{DL} says someone else drove.")],
        role: "Sheriff's deputy",
        exam: [.direct("What happened when you tried to stop the car on {DATE}?", "\"I saw a car with an expired tag and turned on my lights. The car sped away, and I followed until it was abandoned in a cul-de-sac.\""), .direct("What did your dash camera record?", "\"The car speeding away from my lights. It shows the pursuit and how fast the car was going, but the driver isn't clear.\""), .direct("What did you see when you first noticed the car?", "\"A dark sedan with an expired tag on a two-lane road at about 8:10. I turned on my lights, and it sped up and turned onto a side street.\""), .direct("How long did the pursuit last?", "\"About two minutes. The car turned into a cul-de-sac, and the driver stopped near the end and both doors opened.\""), .direct("What did you find in the cul-de-sac?", "\"The car was empty, a phone lay in the console, and a set of keys was in a hedge near the curb. I searched the yards and found {D} behind a shed.\""), .direct("Where were the keys, and what did you do to find them?", "\"They were in a hedge near the cul-de-sac. I had another deputy help me search the yard line by line before we found them.\""), .cross("Did you see who was driving the car?", "\"No. I couldn't see the driver's face. I followed the car, and when it stopped, nobody was in it.\""), .cross("{DL} says someone else drove, doesn't {D.he}?", "\"I can't dispute that someone else could have been driving, but {DL} was the one I found hiding.\""), .cross("Did you see {DL} get out of the car?", "\"No. By the time I got to the cul-de-sac, the car was empty. I didn't see anyone leave it.\""), .cross("Did you see a second person leave the car?", "\"I thought I saw a figure run toward the back of a house, but it was dark and I couldn't tell.\""), .cross("Was {D} wearing anything that tied {D.him} to the car?", "\"No. {D.He} wore ordinary clothes, and I found nothing in the pockets from the car.\"")],
        theory: ("{D} fled from a deputy.", "Another driver."),
        allocution: "\"I panicked.\"",
        truths: ("{DL}'s phone was in the car's console.", "A neighbor saw a different person in a hooded jacket run from the car."),
        defendant: [.direct("Were you driving the car?", "\"No. Someone else was driving. I was a passenger, and when the car stopped, I got out and ran because I was scared.\""), .direct("Why did you hide behind the shed?", "\"I was afraid of getting in trouble. I didn't want to be blamed for what the driver did. I panicked and hid.\""), .direct("Who was driving?", "\"I don't want to name anyone. I know that makes it harder. But I wasn't behind the wheel, and I didn't throw any keys.\""), .direct("Walk us through how you came to be in that car.", "\"A friend offered me a ride home from a gathering. I got in the front passenger seat and we were a few minutes into the drive.\""), .direct("What happened when the lights came on?", "\"The driver said something about an expired tag and sped up. I told the driver to stop and the driver wouldn't.\""), .direct("Why did you run?", "\"I panicked. The driver ran, and I followed, and I ended up hiding behind a shed.\""), .cross("You were found alone hiding near the car, weren't you?", "\"Yes. Everyone else was gone. I know how that looks. But I was a passenger, not the driver.\""), .cross("The keys were in a hedge right by the car, correct?", "\"That's what the deputy says. I didn't put them there. I didn't touch them.\""), .cross("You ran from the deputy, didn't you?", "\"Yes. I ran because I was scared. I know it was a bad decision, and I wish I had stayed put.\""), .cross("Why won't you tell the jury who the driver was?", "\"I don't want to get a friend in trouble, and I don't want anyone to think I'm lying.\""), .cross("You were found alone near the car with the keys in a hedge. How do you explain that?", "\"I didn't throw them. The driver may have tossed them as we ran, and I never touched them.\"")],
        openings: ("A deputy tried to stop a car with an expired tag, and it sped off from the lights. It was abandoned in a cul-de-sac with keys in a hedge, and {D} was found hiding behind a shed. The State will show the dash camera and the keys.", "The defense will present a passenger who ran in a panic, and a deputy who never saw who was driving. Hiding is not the same as fleeing in a car."),
        closings: ("The car fled, the keys went into a hedge, and {D} was the one hiding behind a shed. Everything points to the person who ran.", "No one saw who was driving. {D} was found near the car, but that doesn't make {D} the driver. The State has not proved who was behind the wheel."),
        timeline: [(0, "8:10 p.m.: the deputy sees the tag."), (0, "8:12 p.m.: the car flees."), (0, "8:20 p.m.: {DL} is found behind a shed.")],
        identified: "A dash camera.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let kayakDockTheft = SmallCases.make(
        key: "story.kayakDockTheft",
        category: .property,
        headlines: ["Kayak Cut From Dock Cable at Lakeside Rental", "Sticker on Hull Led Deputy to Truck Bed"],
        law: "misdLarceny",
        spec: "Stole a kayak valued at $650 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}'s kayak, worth $650, was cut from a dock cable on {DATE}. A deputy later saw a kayak with a rental sticker in the bed of {D}'s truck. {DL} says {D.he} bought the kayak at a flea market.",
        state: [E(.physical, 3, "Kayak", "A kayak with {V}'s rental sticker in {D}'s truck.", .search), E(.video, 2, "Dock Camera", "A truck backs to the dock at dawn.")],
        defense: [E(.statement, 1, "Flea Market", "{DL} says {D.he} bought the kayak at a flea market.")],
        role: "Kayak owner",
        exam: [.direct("What was taken from the dock on {DATE}?", "\"My kayak, worth $650, was cut from a dock cable. It had a rental sticker on it, so it was easy to recognize.\""), .direct("Where did you find your kayak?", "\"A deputy later saw a kayak with my rental sticker in the bed of {D}'s truck. I identified it as mine by the sticker.\""), .direct("Where was the kayak kept, and how was it secured?", "\"On a floating dock at a public ramp, locked by a steel cable through the handle. It had a rental company's sticker on the side because I'd bought it used.\""), .direct("What does the dock camera show?", "\"A pickup backs up to the ramp at about six in the morning. Someone gets out, cuts something at the dock, loads the kayak, and drives away.\""), .direct("How did the kayak turn up again?", "\"A deputy noticed it in the bed of a pickup at a gas station two days later. The sticker was on the side, and I identified it by a scratch on the stern.\""), .direct("What proof do you have that the kayak found in the truck was yours?", "\"I had the serial number and a photo of it hanging from the dock cable. The number on the hull matched my purchase record.\""), .cross("Did you see {DL} take the kayak?", "\"No. I wasn't there at dawn. I only know what the camera shows and what the deputy found in the truck later.\""), .cross("Couldn't someone have sold {DL} the kayak?", "\"It's possible. I don't know how it got from the dock to {D.his} truck. I only know it's mine.\""), .cross("Can you see the driver on the camera?", "\"Not clearly. The camera shows a truck, and I can't make out the face. I can only say it matches the truck the kayak was found in.\""), .cross("Could you see the driver or the license plate on the camera?", "\"Not the plate, and the person's face is hidden by a cap. The truck is dark blue with a ladder rack.\""), .cross("How often do kayaks go missing from that dock?", "\"It's happened a couple of times in the past few years. People tend to cut the cable and take them.\"")],
        theory: ("{D} took a kayak from a dock.", "A flea market purchase."),
        allocution: "\"I took it. I'm sorry.\"",
        truths: ("A cut cable piece was in {DL}'s truck.", "A flea market vendor's receipt book lists a kayak sale to {DL} for $80."),
        defendant: [.direct("How did you come to have this kayak?", "\"I bought it at a flea market. The seller had a few things for sale, and the price was good. I put it in my truck.\""), .direct("Did you notice the rental sticker?", "\"Yes, but I thought it was a used kayak from a rental company. I didn't think that meant it was stolen.\""), .direct("Were you at the dock that morning?", "\"No. I've never been to that dock. I didn't cut any cable, and I didn't take anything from it.\""), .direct("Tell us how you came to have the kayak.", "\"I bought it from a vendor at a flea market for eighty dollars. It was lying on a tarp with a few other water items.\""), .direct("What did you think about the rental sticker?", "\"I assumed it came from a rental fleet that sold it off. A lot of used kayaks have those stickers.\""), .direct("What were you doing the morning of the theft?", "\"At home, getting ready for work. I never went near that ramp.\""), .cross("Your truck matches the one on the camera, doesn't it?", "\"It's a common truck. A lot of trucks look like that. I wasn't there, and I can't speak for the one in the video.\""), .cross("You can't name the flea market seller, can you?", "\"No. I paid cash and didn't get a name. I know how that sounds, but it's what happened.\""), .cross("A rental sticker doesn't go on kayaks people sell, does it?", "\"I didn't think about that. I should have asked more questions. I thought I got a bargain.\""), .cross("Your truck looks like the one on the camera. Is that a coincidence?", "\"It's a common color and has a rack like a lot of trucks around here. I wasn't there.\""), .cross("Why can't you name the seller?", "\"It was a cash deal and I didn't get a name. I have the receipt book entry from the vendor, though.\"")],
        openings: ("{V}'s $650 kayak was cut from a dock cable at dawn. A dock camera shows a truck backing up, and a deputy later found a kayak with {V}'s rental sticker in the bed of {D}'s truck. The State will show the kayak and the video.", "Jurors will also see a flea market purchase, a common truck, and a buyer who never went near the dock. Owning a stolen kayak is not stealing it."),
        closings: ("A cut cable, a truck at the dock at dawn, and {V}'s kayak with {V}'s sticker in {D}'s truck. The simplest explanation is the right one.", "{D} bought a kayak at a flea market and carried it openly. The camera doesn't show a face. The State has not proved {D} took it or knew it was stolen."),
        timeline: [(0, "6 a.m.: a truck backs to the dock."), (0, "6:10 a.m.: the cable is cut."), (0, "9 a.m.: {V} finds the dock empty.")],
        identified: "The rental sticker.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let altereCheckMail = SmallCases.make(
        key: "story.altereCheckMail",
        category: .whiteCollar,
        headlines: ["Altered Check Cashed After Mail Theft", "Bank Notes Different Ink on Payee Line"],
        law: "uttering",
        spec: "Offered a forged check for $780 to a bank, knowing it to be forged, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} mailed a $78 check to a utility. The check was stolen from the mailbox, altered to read $780 and a new payee, and cashed by {D} on {DATE}. {DL} says a friend gave {D.him} the check as payment for work.",
        state: [E(.document, 3, "Check", "A $78 check altered to $780 with a different ink."), E(.video, 3, "Bank Camera", "{D} cashes the check.")],
        defense: [E(.statement, 1, "Payment for Work", "{DL} says a friend paid with the check.")],
        role: "Bank teller",
        exam: [.direct("What did you see about the check that was cashed?", "\"It was a $78 check altered to read $780, and it carried a different payee. The altered figures were in a different ink.\""), .direct("Who cashed the check?", "\"{D} cashed it at my window. The bank camera shows {DL} handing it over and receiving the money.\""), .direct("How did you handle the transaction?", "\"I verified the ID and cashed it. At the time, I didn't catch the alteration. It was only later that the original issuer reported it.\""), .direct("What did you notice when the check was presented?", "\"The amount said $780 in a darker ink than the payee's name, and the writing on the amount line was a bit crowded. The payee was a person, not the utility.\""), .direct("What do you do when you cash a check for someone who isn't a customer?", "\"We verify a photo ID, check that the signature is consistent, and compare the amount to the account. {D.his} ID looked valid.\""), .direct("When did the bank learn the check was altered?", "\"Four days later, when {V} reported that the utility hadn't received the $78. We pulled the video and the check itself.\""), .cross("Did anything about the check look wrong at the time?", "\"Not enough for me to stop it. The ink difference was subtle. I processed it like any other check from a customer with ID.\""), .cross("Did {DL} act nervous or rush you?", "\"No. {DL} was calm and polite, and presented valid ID. {DL} behaved like any other customer, and I had no reason to question it.\""), .cross("Do you know who altered the check?", "\"No. I only know who cashed it. I can't say who changed the numbers or the payee.\""), .cross("Did you or your supervisor have any concern about the check?", "\"I thought the ink looked a little off, but not enough to refuse. It's not unusual for checks to be written with different pens.\""), .cross("Did {D} seem to know that the check was altered?", "\"No. {D.He} was calm and answered my questions. I had no sense that anything was wrong.\"")],
        theory: ("{D} cashed an altered stolen check.", "A check received in good faith."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had similar pens in a bag at home.", "The friend later confirmed paying {DL} with the check for a roofing job."),
        defendant: [.direct("How did you get the check?", "\"A friend gave it to me as payment for work I did. I didn't think about it. I brought it to the bank and cashed it.\""), .direct("Did you know it had been altered?", "\"No. It looked normal to me. If I had seen it was changed, I wouldn't have taken it to the bank.\""), .direct("Why did you use your own ID?", "\"Because I had nothing to hide. I thought it was legitimate. I wouldn't have walked into a bank with my own name if I thought I was passing a forged check.\""), .direct("Describe the work you did for your friend for the jury.", "\"I helped with a roofing job for a few days. My friend paid me with a check, saying it was from a client.\""), .direct("How much did you expect to be paid?", "\"About seven hundred dollars for four days. The check read $780, so I thought it was right.\""), .direct("Why did you cash it at the bank rather than deposit it?", "\"I don't have an account there. I cash checks at the bank where my friend said the client banked.\""), .cross("The ink on the amount was different, wasn't it?", "\"I didn't notice. I don't look closely at checks. Looking at it now I can see the difference, but I couldn't then.\""), .cross("You can't name the friend who gave you the check, can you?", "\"I can, but I'd rather not drag anyone into it. I know that makes it harder to believe me.\""), .cross("$780 is a lot for a few hours of work, isn't it?", "\"It was a decent job. I didn't question the amount. I took what I was given, and I didn't think about where it came from.\""), .cross("The ink on the amount was different. Didn't you notice?", "\"I didn't look closely. I looked at the amount and the payee line and saw my name.\""), .cross("You say you can't name your friend. Isn't that convenient?", "\"It's not that I can't. I'd rather not involve someone who may have been tricked as well.\"")],
        openings: ("{V} mailed a $78 check to a utility. It was stolen from the mailbox, altered to read $780 with a new payee, and cashed by {D}. The State will show the altered check and the bank camera.", "The defense evidence includes a worker who was paid by check, walked into a bank with a real ID, and had no idea it had been changed."),
        closings: ("A $78 check changed to $780, in a different ink, cashed by {D} at the window. {D} took the money, and the check was not what it seemed.", "{D} cashed a check given for work, using a real ID at a bank full of cameras. The State has not proved {D} knew the check was altered."),
        timeline: [(-4, "{V} mails the check."), (0, "Noon: {DL} cashes the altered check."), (3, "{V} sees the cleared amount.")],
        identified: "A bank camera and an altered check.",
        mood: .wantsConviction)

    static let fuelCardMisuse = SmallCases.make(
        key: "story.fuelCardMisuse",
        category: .whiteCollar,
        headlines: ["Company Fuel Card Used for Weekend Trips, Landscaper Says", "Receipts Show Pumps Miles From Any Job Site"],
        law: "misdLarceny",
        spec: "Stole gasoline and snacks valued at $412 belonging to {V}, a landscaping company, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}'s landscaping company found its fuel card used 19 times on weekends for $412 in gasoline and snacks, at stations far from any job site. The card was assigned to {D}. {DL} says {D.he} was refueling the crew truck at the owner's request.",
        state: [E(.document, 3, "Card Statement", "19 weekend charges totaling $412."), E(.video, 2, "Station Camera", "{D} at a pump in a personal car.")],
        defense: [E(.statement, 1, "Crew Truck", "{DL} says {D.he} fueled the crew truck.")],
        role: "Landscaping owner",
        exam: [.direct("What did you notice about the company fuel card?", "\"It was used 19 times on weekends for $412 in gasoline and snacks. The stations were far from any job site we had.\""), .direct("Who was the card assigned to?", "\"{D}. The card was assigned to {D.him} for company use. Weekend use at distant stations is not part of anyone's work for us.\""), .direct("What does the station camera show?", "\"{DL} at a pump in a personal car. It isn't one of our work vehicles, and it's not the crew truck.\""), .direct("How is the fuel card supposed to be used?", "\"For company trucks and equipment only. Each employee with a card is told it is for work vehicles, and the monthly statement goes to me.\""), .direct("What did the statement show?", "\"Nineteen charges on weekends over three months, adding up to $412. They were at stations twenty to thirty miles from our job sites.\""), .direct("What did you do after seeing the camera footage?", "\"I asked a station for the video. It shows {DL} at the pump in a gray sedan, not the crew truck, and then {DL} goes inside for snacks.\""), .cross("{DL} says {D.he} was fueling the crew truck at your request, doesn't {D.he}?", "\"I sometimes asked {D.him} to fuel the crew truck on a weekday. I never authorized weekend personal use at distant stations.\""), .cross("Did you ever tell {DL} not to use the card on weekends?", "\"I didn't say that in so many words. It was understood the card was for company vehicles. I trusted {D.him}, and that was my mistake.\""), .cross("Did you review the card statements monthly?", "\"Not as closely as I know I should have. I noticed the pattern after a few weeks and started checking. That's when I saw the weekend charges.\""), .cross("Did you tell {D} the card could not be used on weekends?", "\"I didn't say it in so many words. I told {DL} it was for company vehicles, but we had never defined weekends.\""), .cross("Did you sometimes ask the defendant to fuel the crew truck on a weekend?", "\"Yes, once or twice a month. It would be reasonable to see a few weekend charges, but not nineteen.\"")],
        theory: ("{D} used a company card for personal fuel.", "Fuel for the crew truck."),
        allocution: "\"I'm sorry. I'll repay it.\"",
        truths: ("The camera shows a sedan, not the crew truck.", "The owner had texted {DL} to fuel the crew truck and the owner's own car on weekends."),
        defendant: [.direct("What was the fuel card for?", "\"It was for fueling the crew truck and company vehicles. The owner told me to keep the truck filled, including on weekends.\""), .direct("Did you use it for a personal car?", "\"I fueled other vehicles at times, in the course of working for the owner. I thought that was covered. I didn't think I was stealing.\""), .direct("Why were the stations far from the job sites?", "\"I was on the road, running errands for the business. I fueled up where I could. I wasn't trying to get away with anything.\""), .direct("Explain to the jury how you were given the card.", "\"The owner gave it to me when I became crew lead. I was told to keep the trucks fueled and to keep the receipts.\""), .direct("Whose vehicles did you fuel on weekends?", "\"The crew truck and the owner's car on a few occasions, when the owner asked. I also did fuel my own car once or twice.\""), .direct("What did your boss say about the weekend fuel cards when you were first given the card?", "\"The owner told me to fuel the crew truck and the owner's own car on weekends. I took that to mean the card covered both, and I never asked for it in writing.\""), .cross("Nineteen weekend charges is a lot, isn't it?", "\"It adds up, I know. I wasn't tracking each one. I thought it was part of the arrangement.\""), .cross("The camera shows you at a pump in a personal car, doesn't it?", "\"It shows a car that wasn't the crew truck. I'm not going to say otherwise. I understood I was allowed to do that.\""), .cross("The owner says that wasn't allowed, doesn't {V.he}?", "\"I know. We remember it differently. I never meant to cheat anyone, and I thought it was fine.\""), .cross("The camera shows you at a pump in a sedan, not the crew truck. How do you explain that?", "\"It was a sedan I used to run errands for the company that day. I wasn't tracking each use.\""), .cross("Nineteen weekend charges and snacks. Isn't that more than the crew truck needs?", "\"It adds up, and I'm not going to argue that every purchase was necessary. I kept some receipts and lost others.\"")],
        openings: ("{V}'s landscaping company found its fuel card used 19 times on weekends for $412 in gas and snacks, at stations far from any job. The card was assigned to {D}, and a station camera shows {D} in a personal car. The State will show the statement and video.", "The defense will point you to an employee who understood {D.his} role included keeping vehicles fueled, including on weekends, and who used the card openly. This was a misunderstanding."),
        closings: ("Nineteen weekend charges, stations far from every job, and a camera showing a personal car at the pump. The card was for the business, and {D} used it for something else.", "An owner who asked for weekend fueling and an employee who understood the arrangement. The State has not proved {D} meant to steal from the company."),
        timeline: [(-60, "{DL} is given the card."), (0, "The owner reviews the monthly statement."), (1, "The owner asks {DL} about the charges.")],
        identified: "A card statement.",
        mood: .wantsConviction)

    static let hotelRoomTrashed = SmallCases.make(
        key: "story.hotelRoomTrashed",
        category: .property,
        headlines: ["Hotel Room Left With Holes in Wall and Ripped Curtains", "Cleaners Find Broken Furniture"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a hotel, causing damage of $3,200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Housekeeping found a hotel room with holes in the wall, a broken desk and ripped curtains on {DATE}. The damage was $3,200. {D} had rented the room. {DL} says a party of guests {D.he} did not invite caused it.",
        state: [E(.document, 3, "Damage Report", "Wall holes, desk and curtains; $3,200 in repairs."), E(.document, 2, "Guest Folio", "The room was rented to {D}.")],
        defense: [E(.statement, 1, "Uninvited Guests", "{DL} says uninvited guests caused it.")],
        role: "Hotel manager",
        exam: [.direct("What did housekeeping find in the room on {DATE}?", "\"Holes in the wall, a broken desk, and ripped curtains. The damage was extensive, and the repairs came to $3,200.\""), .direct("Who had rented the room?", "\"{D}. The guest folio shows the room rented to {D.him}, who checked in and was the only registered guest.\""), .direct("What did {DL} say about it?", "\"{D.He} said uninvited guests caused the damage. I wasn't there during the night, but the room was left in that condition at checkout.\""), .direct("Who was assigned to the room, and when did housekeeping enter?", "\"{D.He} had it from Friday evening for one night, with a late checkout at noon. Housekeeping went in at nine on Saturday morning because the do-not-disturb sign was off.\""), .direct("Describe the damage in detail.", "\"Three holes the size of a fist in the drywall, a desk with a snapped leg, torn curtains, and a stained carpet. The repair total was $3,200.\""), .direct("What do your keycard records show?", "\"Eleven different cards opened that door during the night. Only two were issued to {D.him}, and the rest were cards from other rooms or spares.\""), .cross("Do you know how many people were in the room?", "\"No. I can't tell you the number. I wasn't there. The folio shows one guest, but I can't say who else may have been in the room.\""), .cross("Did {DL} report the damage or any disturbance?", "\"I don't recall a call to the front desk. I can only say the room was damaged when housekeeping got there.\""), .cross("Did you see {DL} cause any damage?", "\"No. I never saw {DL} or anyone damaging anything. I only know the room's condition and who rented it.\""), .cross("Did {D} contact the front desk at any time that night?", "\"No. We have no record of a call, and the night clerk told me nobody reported a disturbance.\""), .cross("Did other guests complain about noise from that room?", "\"Two guests on that floor complained about noise at about two in the morning. The night manager knocked and the noise stopped for a while.\"")],
        theory: ("{D} wrecked a hotel room.", "Uninvited guests."),
        allocution: "\"I'll pay for the damage.\"",
        truths: ("The hallway camera showed only two guests all night.", "Keycard logs show eleven different cards opened the room that night."),
        defendant: [.direct("What happened in your room that night?", "\"A group of people I didn't invite showed up and things got out of hand. I couldn't get them to leave, and they damaged things.\""), .direct("Who were these people?", "\"I don't know all of them. Some were people I'd met earlier at the hotel. I never invited a party, and I didn't want it.\""), .direct("Why didn't you call the front desk?", "\"I should have. I was afraid of being blamed. I thought I could handle it myself, and it only got worse.\""), .direct("Tell the jury why you rented the room.", "\"It was a night away with a couple of friends for a birthday. I rented one room, and we planned to go out and come back by midnight.\""), .direct("Who was in the room when you left?", "\"A few friends. When I came back around four, the room was full of people I had never met and the door was propped open.\""), .direct("What did you do when you saw the damage?", "\"I was in shock. I asked everyone to leave and then sat down on the bed. I was afraid I'd be blamed, so I didn't call the front desk.\""), .cross("The room was rented to you, wasn't it?", "\"Yes. That's why I'm here. I'm responsible for who I let in, and I let too many people in. I accept that.\""), .cross("The damage was $3,200, correct?", "\"That's what they say. I'm willing to discuss paying for my share, but I didn't punch walls or break the desk.\""), .cross("You didn't stop anyone, did you?", "\"I tried to ask people to leave. It didn't work. I didn't call security, and I wish I had.\""), .cross("The keycard log shows eleven cards. Whose were they?", "\"I gave a few friends copies, and I don't know how the rest got in. I didn't track it.\""), .cross("You didn't report the damage. Isn't that because you were responsible for it?", "\"No. I didn't report it because I was embarrassed and scared, and I didn't know what to say.\"")],
        openings: ("Housekeeping found a hotel room with holes in the wall, a broken desk, and ripped curtains, with $3,200 in damage. The room was rented to {D}. The State will show the damage report and the guest folio.", "The defense will present a room that was overrun by uninvited guests, a renter who couldn't control the crowd, and no proof {D} personally broke anything."),
        closings: ("Holes in the wall, a broken desk, torn curtains, and $3,200 in repairs. The room was rented to {D}, and {D} is responsible for what happened in it.", "A renter who lost control of a room is not a vandal. No one saw {D} break anything. The State has not proved {D} did the damage."),
        timeline: [(0, "11 p.m.: {DL} leaves the room."), (1, "4 a.m.: {DL} returns."), (1, "9 a.m.: housekeeping reports the damage.")],
        identified: "Hotel records.",
        mood: .indifferent)

    static let weddingGiftBox = SmallCases.make(
        key: "story.weddingGiftBox",
        category: .property,
        headlines: ["Gift Card Box Taken From Wedding Reception Table", "Photographer's Frames Show Guest at Gift Table"],
        law: "misdLarceny",
        spec: "Stole gift cards and cash valued at $1,200 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A decorated box holding $1,200 in cards and cash vanished from the gift table at {V}'s wedding reception on {DATE}. The photographer's frames showed {D} carrying the box toward the door. {DL} says {D.he} was moving it to a safe place.",
        state: [E(.video, 3, "Photographer's Video", "{D} carries the box toward the exit."), E(.statement, 2, "Guest", "The box was missing after the toast.")],
        defense: [E(.statement, 1, "Safe Place", "{DL} says {D.he} moved it to a safe place.")],
        role: "Bride or groom",
        exam: [.direct("Please describe your wedding and the gift table.", "\"We were married on a Saturday in a banquet hall with about eighty guests. There was a decorated box on the gift table where people left cards and cash.\""), .direct("What was in the gift box?", "\"$1,200 in cards and cash from our guests. It was decorated and sat on the gift table at the reception.\""), .direct("How did you learn it was gone?", "\"It was missing after the toast. A guest told me, and we searched the room before looking at the photographer's footage.\""), .direct("What does the photographer's video show?", "\"It shows {D} carrying the box toward the exit. The frames are clear that it is the same box.\""), .direct("When did you realize the box was gone?", "\"After the toast, when I went to check the table. The box wasn't there, and a guest told me they'd seen someone carry it toward the door.\""), .direct("What was in the box?", "\"About $1,200 in cash and cards from friends and family. Some of the cards had checks, and we had no way to cancel them quickly.\""), .cross("{D} says the box was moved to a safe place, doesn't {D.he}?", "\"I do not know of any safe place. Nobody told me about it, and I never asked anyone to move it.\""), .cross("A guest or relative could have asked the defendant to carry it, couldn't they?", "\"A relative may have. I did not ask, and I cannot say whether someone else did.\""), .cross("{D} was a guest at the reception, wasn't {D.he}?", "\"Yes. {D.He} was invited and had every right to be there.\""), .cross("Did anyone ask the defendant to move the box for safekeeping?", "\"Not that I know of. Some relatives told me later that someone might have, but no one said who.\""), .cross("Did you know the defendant before the wedding?", "\"No. {DL} came as a plus-one of a cousin, and I'd only met {DL} briefly in the receiving line.\"")],
        theory: ("{D} took the gift box.", "A guest moving it."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} drove away before the cake.", "The couple's relative later said {DL} was asked to carry the box to the car for safekeeping."),
        defendant: [.direct("Did you take the gift box?", "\"No. I moved it. I was told to carry it to the car for safekeeping, and I thought it was the right thing to do.\""), .direct("Why did you leave before the cake?", "\"I had a headache and I felt unwell. I told someone I was leaving, and I went home.\""), .direct("Whose idea was it to move the box?", "\"A relative of the couple asked me to take it to the car. I did not question it.\""), .direct("Explain to the jury why you were at the wedding.", "\"I came as a guest of a cousin. I'd never met the couple, but I was invited and I wore a suit and brought a gift.\""), .direct("Why did you pick up the box?", "\"A relative of the couple asked me to carry it out to a car. The relative said it was too heavy and should go somewhere safe.\""), .direct("What did you do with it?", "\"I took it to a car in the parking lot and put it in the trunk, as I was told. Then I felt dizzy and went home.\""), .cross("You left with the box and did not come back, did you?", "\"I left because I was sick. I did not realize the box mattered that much.\""), .cross("The cards and cash were meant for the couple. Where are they now?", "\"I do not have them. I put the box in the car for safekeeping, and I left.\""), .cross("Why would a relative ask you, a guest, to carry a box of money?", "\"I do not know. I was close enough to be asked. I thought it was a normal favor.\""), .cross("You left before the cake and didn't come back. Isn't that suspicious?", "\"I had a headache and wasn't feeling well. I should have told someone I was leaving.\""), .cross("You can't tell the jury which relative asked you to carry it. Why not?", "\"I didn't know anyone there well, and I didn't ask a name. I took the relative's word that it was fine.\"")],
        openings: ("A decorated box holding $1,200 in cards and cash vanished from the gift table at a wedding reception. The photographer's video shows {D} carrying it toward the exit.", "The defense evidence will establish that {D} was asked to carry the box to the car for safekeeping and left early with a headache. {D} took nothing."),
        closings: ("A box of wedding gifts, a video of {D} carrying it to the door, and a guest who left before the cake. The couple never saw their $1,200 again.", "A guest was asked to move a box for safekeeping and did, then went home sick. Carrying a box in front of a photographer is not how a thief behaves."),
        timeline: [(0, "6 p.m.: the toast."), (0, "6:20 p.m.: {DL} carries the box out."), (0, "7 p.m.: the couple finds it missing.")],
        identified: "The photographer's video.",
        mood: .indifferent)

    static let busPassingStopArm = SmallCases.make(
        key: "story.busPassingStopArm",
        category: .traffic,
        headlines: ["Driver Passes School Bus With Stop Arm Out", "Bus Camera Records Plate and Children Crossing"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, passing a stopped school bus, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A school bus stopped with its red lights and stop arm out at 7:20 a.m. on {DATE}. A car passed it as children crossed. The bus camera recorded the plate, registered to {D}. {DL} says the lights were not visible in the glare.",
        state: [E(.video, 3, "Bus Camera", "A car passes the stop arm as children cross."), E(.document, 2, "Registration", "The plate is registered to {D}.")],
        defense: [E(.statement, 1, "Glare", "{DL} says glare hid the lights.")],
        role: "School bus driver",
        exam: [.direct("What happened at 7:20 on the morning of {DATE}?", "\"I stopped the bus with the red lights flashing and the stop arm out. Children were crossing in front of the bus when a car passed.\""), .direct("What did your bus camera record?", "\"A car passes the stop arm as the children cross. The camera caught the plate clearly, and it's registered to {D}.\""), .direct("How close were the children?", "\"They were in the road, and the car went past while they were crossing. I had to shout, and I'm lucky none of them were struck.\""), .direct("Describe the route and the stop where this happened.", "\"A rural two-lane road with a stop for about nine children at a corner. I put the red lights on and extended the stop arm about two hundred feet before the stop.\""), .direct("What did you see as the car came toward you?", "\"A silver sedan approached from the opposite direction and did not slow. It passed the stop arm at about thirty miles an hour while children were in the road.\""), .direct("What did you do?", "\"I hit the horn and held the children back with my arm. I wrote down the plate and reported it as soon as the children were seated.\""), .cross("{DL} says glare hid the lights, doesn't {D.he}?", "\"I can't speak to glare in another driver's eyes. I can say the lights were on and the arm was out, and the camera shows them.\""), .cross("Was anyone hit or hurt?", "\"No. The children were frightened, but nobody was struck. It was close, and I don't want to think about what could have happened.\""), .cross("Can you tell who was driving the car?", "\"The plate is registered to {D.him}. I couldn't tell the driver's face from the camera, and I can't identify who was behind the wheel.\""), .cross("How far away was the car when you first saw it?", "\"About three hundred feet. The road was straight, so I should have been able to see it clearly.\""), .cross("Was the sun in your eyes at that time?", "\"The sun was low in the east, behind me and off to the side, so I wasn't blinded. I can't say what it did to a driver coming the other way.\"")],
        theory: ("{D} passed a stopped bus.", "Glare."),
        allocution: "\"I'm very sorry.\"",
        truths: ("{DL} had passed the same bus the week before.", "The district mechanic found the bus's stop-arm light burned out."),
        defendant: [.direct("Did you pass the bus?", "\"I went past it, yes. I didn't see the lights flashing. The glare was bad, and I didn't realize the bus had stopped.\""), .direct("Why didn't you see the stop arm?", "\"The sun was in my eyes. I was looking ahead and didn't notice the lights until I was already past. I would never pass a stopped bus on purpose.\""), .direct("Did you see the children?", "\"Not until it was too late. I felt sick when I realized they were crossing. I'm very sorry that happened.\""), .direct("Please describe your drive that morning.", "\"I was driving to work along that road as I do every day. The sun was low and right in my eyes.\""), .direct("What did you see as you came to the corner?", "\"A bright flash and a bus shape, and not much else. I thought it was parked.\""), .direct("How did you find out what had happened?", "\"A deputy called me later and described it. I felt sick, and I told the deputy I wanted to talk to the driver and apologize.\""), .cross("The camera shows the stop arm out, doesn't it?", "\"I know. I've seen it. I just didn't see it at the time. I wasn't paying attention the way In hindsight, yes.\""), .cross("Red lights and a stop arm are hard to miss, aren't they?", "\"They are, usually. I can't explain it, except that the glare was on my side. I know that sounds like an excuse.\""), .cross("It's your car, correct?", "\"Yes, the plate is mine. I'm not denying I was driving. I'm saying I didn't see the lights, and I wish I had.\""), .cross("Red lights and a stop arm are hard to miss. Why didn't you see them?", "\"The glare washed everything out. I know how that sounds, but I'm telling you what I saw.\""), .cross("You've driven that road every day. Didn't you know a bus stopped there?", "\"I knew it was a bus route. I'd never been there at that time of the morning, because I'd changed my shift.\"")],
        openings: ("A school bus stopped at 7:20 in the morning with its red lights flashing and stop arm out. A car passed it as children crossed, and the bus camera recorded the plate, registered to {D}. The State will show the video.", "The defense evidence includes a driver blinded by glare who never saw the lights or the children. A failure to see is not the same as choosing to ignore."),
        closings: ("Red lights, a stop arm, children crossing, and a car that passed anyway. The camera caught the plate, and it's {D}'s. The law protects those children for a reason.", "{D} was driving into the glare and did not see the lights. No one was hit. The State has not proved {D} knowingly passed a stopped bus."),
        timeline: [(0, "7:18 a.m.: the bus stops."), (0, "7:20 a.m.: the car passes."), (0, "7:30 a.m.: the driver reports the plate.")],
        identified: "A bus camera.",
        mood: .wantsConviction)

    static let gymLockerWallet = SmallCases.make(
        key: "story.gymLockerWallet",
        category: .property,
        headlines: ["Wallet Taken From Gym Locker With Cut Lock", "Membership Records Name Visitor"],
        law: "misdLarceny",
        spec: "Stole a wallet and $210 in cash belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} returned to a gym locker on {DATE} to find a cut lock and a missing wallet with $210. Membership records showed {D} had visited that hour as a guest. A card from the wallet was used at a gas station. {DL} says {D.he} found the wallet on a bench.",
        state: [E(.document, 3, "Guest Log", "{D} signed in as a guest at 6:05 p.m."), E(.digital, 3, "Card Charge", "The wallet's card was used at a gas station at 7 p.m.")],
        defense: [E(.statement, 1, "Found Wallet", "{DL} says {D.he} found the wallet on a bench.")],
        role: "Gym member",
        exam: [.direct("Tell us how you use the gym and your locker.", "\"I go three or four evenings a week after work. I use the same locker in the second row and I keep a padlock on it that I bought myself.\""), .direct("What did you find at your gym locker on {DATE}?", "\"The lock was cut, and my wallet was gone with $210 in it. I had left it in the locker before my workout.\""), .direct("What did the gym's records show?", "\"{D} signed in as a guest at 6:05 p.m., about the time I was working out. That was during the hour the wallet went missing.\""), .direct("What happened with your cards?", "\"A card from my wallet was used at a gas station at 7 p.m. I got a notice from the bank and reported it right away.\""), .direct("What did you find when you came back from your workout?", "\"The padlock was lying on the bench, cut through. The locker was open and my wallet was gone, along with $210 in cash.\""), .direct("How did the gym help you after that?", "\"The manager pulled the guest log and the front desk camera. A guest named {DL} had signed in at 6:05, about a half hour before my locker was cut.\""), .cross("Did you see {DL} near your locker?", "\"No. I didn't see {D.him} at all. I was working out. I only know about {D.him} from the guest log.\""), .cross("Did {DL} have any connection to you?", "\"No. I'd never met {D.him}. I don't know {D.him}, and there was nothing between us before that day.\""), .cross("Other people were in the gym, weren't they?", "\"Yes, plenty. Members and guests were coming and going. I can't say who else was near the lockers.\""), .cross("Did you see anyone near your locker?", "\"No. I was on a treadmill with earbuds in, and I didn't look toward the locker room.\""), .cross("Did you ever see {D} before that night?", "\"No. I'd never met {DL}, and I couldn't pick {DL} out of a crowd.\"")],
        theory: ("{D} cut a locker and took a wallet.", "A found wallet."),
        allocution: "\"I'm sorry.\"",
        truths: ("A bolt cutter was in {DL}'s gym bag.", "The gas station camera shows a different person using the card at 7 p.m."),
        defendant: [.direct("Why were you at the gym?", "\"I was a guest, trying it out. I signed in at 6:05 and worked out. I wasn't there for anything else.\""), .direct("Where did the wallet come from?", "\"I found it on a bench in the locker area. It was just sitting there. I picked it up, thinking I'd turn it in later.\""), .direct("Did you cut a lock?", "\"No. I never cut anything. The wallet was on a bench, not in a locker. I wouldn't have broken into anything.\""), .direct("Tell us why you came to the gym as a guest.", "\"A friend gave me a free pass to try it out. I signed in at the front desk and used the machines for about forty minutes.\""), .direct("How did you come to have a wallet?", "\"I found it on a bench in the locker room when I went to change. It had cards and cash, and I put it in my bag.\""), .direct("What were you going to do with it?", "\"Turn it in at the desk. I got distracted and left it in my bag, and I should have handed it over right away.\""), .cross("Your card was used at a gas station, wasn't it?", "\"I'm told that a card from the wallet was used at 7. I didn't use it. I don't know who did.\""), .cross("You didn't turn the wallet in, did you?", "\"No. I meant to, but I got busy and left with it. I should have given it to the front desk, and I regret it.\""), .cross("You were a guest only that day, weren't you?", "\"Yes. It was my first time there. That's why I wasn't familiar with how to turn in lost items.\""), .cross("You didn't turn in the wallet. Isn't that exactly what a thief does?", "\"I understand how it looks. I meant to return it, and I'm sorry that I didn't.\""), .cross("A bolt cutter was in your gym bag, wasn't it?", "\"Yes. I carry it for work and I forgot it was in there. I did not use it on that lock, and I was not near the lockers when it was cut.\""), .cross("The wallet had $210 in it when you say you found it, didn't it?", "\"I did not count it. I saw it on a bench, and I thought I could find the owner by looking at the license inside.\"")],
        openings: ("{V} came back to a gym locker to find the lock cut and a wallet with $210 gone. {D} had signed in that hour as a guest, and a card from the wallet was used at a gas station an hour later. The State will show the guest log and the card record.", "The defense will point you to a guest who found a wallet on a bench, never cut a lock, and had no connection to the card charge. Being in the building is not stealing."),
        closings: ("A cut lock, a missing wallet, a guest signed in at 6:05, and a card used at 7. The timeline fits one person.", "A wallet on a bench, a guest who forgot to turn it in, and no witness to a cut lock or the card charge. The State has not tied {D} to either."),
        timeline: [(0, "6:05 p.m.: {DL} signs in as a guest."), (0, "6:40 p.m.: the lock is cut."), (0, "7 p.m.: the card is used.")],
        identified: "A guest log and a card charge.",
        mood: .indifferent)

    static let ediblesAtFestival = SmallCases.make(
        key: "story.ediblesAtFestival",
        category: .drugs,
        headlines: ["Festival Security Finds Edibles in Bag at Gate", "Deputy Counts 40 Gummies"],
        law: "possMarijuana",
        spec: "Possessed marijuana, in the form of edible gummies, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Security at a music festival gate searched {D}'s bag on {DATE} and found 40 gummies. A lab confirmed THC. {DL} says {D.he} thought they were hemp-based and legal.",
        state: [E(.physical, 3, "Gummies", "40 THC gummies in a bag.", .search), E(.forensic, 3, "Lab Report", "The gummies contain THC above the legal limit.")],
        defense: [E(.statement, 1, "Hemp", "{DL} says {D.he} thought they were legal hemp.")],
        role: "Security supervisor",
        exam: [.direct("Tell the jury about your role at the festival.", "\"I supervise security at the main gate. We check bags and tickets, and our search is posted on signs and in the festival rules.\""), .direct("What did your team find at the festival gate on {DATE}?", "\"We searched {D}'s bag at the entrance and found 40 gummies. They were packaged together and looked like candy.\""), .direct("What did the lab find?", "\"The gummies contain THC above the legal limit. We sent them to the lab to confirm, and the report came back positive.\""), .direct("Why does that matter at a festival?", "\"Large numbers of people, including young people, attend. Forty gummies with THC isn't a small personal amount, and we take it seriously at the gate.\""), .direct("How did your team come to find the gummies?", "\"A guard asked {DL} to open the bag and found a zip bag with forty gummies in several colors. The guard called me over.\""), .direct("What does the festival's policy say about edibles?", "\"No outside drugs of any kind, including edibles and cannabis products. The rules are on the website and on signs at the gate.\""), .cross("{DL} says {D.he} thought they were hemp-based and legal, doesn't {D.he}?", "\"I'm not the one to say what's legal. I can tell you the lab found THC above the limit.\""), .cross("Was {DL} cooperative at the gate?", "\"Yes. {D.He} opened the bag and answered my questions. {D.He} wasn't hostile or trying to run.\""), .cross("Did you see {DL} sell or hand any to anyone?", "\"No. The gummies were in the bag when we found them. I have no evidence {DL} sold or shared any of them.\""), .cross("Did the packaging say anything about THC?", "\"The label said it was hemp-derived, and I didn't see a THC number. The lab later found THC above the legal limit.\""), .cross("Did {D} try to hide the bag or leave?", "\"No. {D.He} opened the bag when asked and answered every question. {D.He} stayed until deputies arrived.\"")],
        theory: ("{D} had THC gummies.", "A hemp purchase."),
        allocution: "\"They were mine.\"",
        truths: ("The label listed 10 mg THC per piece.", "The package carried a 'hemp-derived, federally legal' label and no THC warning."),
        defendant: [.direct("Where did you get the gummies?", "\"I bought them from a shop that sold hemp products. I thought they were hemp-based and legal, not the kind with THC.\""), .direct("Why did you bring 40 of them?", "\"I was going for the weekend with friends. I thought it would be fun to share. I had no idea they contained THC above the limit.\""), .direct("What did you do when security found them?", "\"I told them exactly where I got them and what I thought they were. I didn't try to hide anything or argue.\""), .direct("Tell the jury where you bought the gummies.", "\"From a shop that sells hemp products near my home. The clerk told me they were legal hemp and gave me a bag with a label.\""), .direct("Why did you bring forty to the festival?", "\"I was going for the weekend with three friends. We planned to share them over three days, and I figured it was a fair amount for a group.\""), .direct("What did the label say?", "\"It said hemp-derived and legal under federal law. I didn't see a THC warning, so I didn't think twice.\""), .cross("Forty gummies is a lot for personal use, isn't it?", "\"I know it sounds like a lot. I was planning to share them over three days with a group of friends.\""), .cross("You never tested them, did you?", "\"No. I trusted the shop. I didn't look closely at the label, and I'm paying for that now.\""), .cross("The lab says they contain THC, doesn't it?", "\"Yes. That's what I'm told. I didn't know that, and I'm surprised by it.\""), .cross("Forty gummies is a lot for personal use. Isn't that more than anyone needs?", "\"It sounds like a lot, but I was sharing with friends. I never meant to sell them.\""), .cross("You never had them tested. Why not?", "\"I trusted the shop. I didn't know anyone who tested products, and I assumed the label was accurate.\"")],
        openings: ("Security at a music festival gate searched {D}'s bag and found 40 gummies. A lab confirmed they contained THC above the legal limit. The State will show the gummies and the lab report.", "The defense will present a buyer who believed the gummies were legal hemp products, who opened the bag without argument and shared nothing. A mistaken belief is not a plan to break the law."),
        closings: ("Forty gummies, a lab report confirming THC, and a bag carried to a festival gate. The law sets the limit, and these were over it.", "{D} bought legal-looking hemp gummies and carried them openly. The State has not proved {D} knew they contained illegal levels of THC."),
        timeline: [(0, "4 p.m.: {DL} arrives at the gate."), (0, "4:10 p.m.: security finds the gummies."), (0, "5 p.m.: deputies arrive.")],
        identified: "A lab report.",
        mood: .indifferent,
        doctrines: ["searchSeizure", "mistakeOfFact"])

    static let phantomLandlord = SmallCases.make(
        key: "story.phantomLandlord",
        category: .whiteCollar,
        headlines: ["Renter Pays Deposit on Apartment Listed by Fake Landlord", "Listing Photos Traced to Other City"],
        law: "falsePretenses",
        spec: "Obtained $1,600 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} paid {D} $1,600 for a deposit and first month on {DATE} for an apartment listed online. The apartment belonged to someone else and {D} had no authority. {DL} says {D.he} was the owner's agent and the owner backed out.",
        state: [E(.digital, 3, "Listing", "A listing with {D}'s phone number and photos from another city."), E(.document, 3, "Payment Record", "$1,600 paid to {D}'s account.")],
        defense: [E(.statement, 1, "Owner's Agent", "{DL} says {D.he} was the owner's agent.")],
        role: "Renter",
        exam: [.direct("Tell the jury what you were looking for when you found the listing.", "\"A one-bedroom apartment near my work. I'd just moved to the area and was staying with a friend, so I needed something quickly.\""), .direct("What did you pay {D} for?", "\"$1,600 for a deposit and the first month's rent on an apartment I found in an online listing.\""), .direct("Who owns the apartment?", "\"Someone else. The owner has no connection to {D}, and {DL} had no authority to rent it to me.\""), .direct("What did you receive as an agreement?", "\"A lease that looked like an online template. It was signed by {DL}, not by the owner.\""), .direct("What did the defendant promise, and what did you pay?", "\"That I could move in the next weekend. I paid $1,600 by transfer for the deposit and first month, and {D.he} sent a lease and a set of keys.\""), .direct("What happened when you went to move in?", "\"The keys didn't work. A person answered the door, said they were the owner, and told me they had never heard of {DL}.\""), .cross("{D} says {D.he} was the owner's agent, doesn't {D.he}?", "\"That is what {D.he} says. I was never shown a letter or any proof of that when I paid.\""), .cross("The listing photos came from another city, didn't they?", "\"Yes, I learned later that the photos were from somewhere else. I did not check at the time.\""), .cross("Did you ever meet the owner?", "\"No. I only dealt with {DL}, and I did not think to ask for the owner's contact.\""), .cross("Did the defendant show you any proof that {D.he} could rent the apartment?", "\"I asked once and {DL} said the owner was out of the country. I never saw a letter or text from the owner.\""), .cross("Did you check the listing photos or the address before you paid?", "\"I looked at the address on a map and the photos looked right. I didn't check them against anything.\"")],
        theory: ("{D} took a deposit on an apartment {D.he} did not control.", "An agent whose owner backed out."),
        allocution: "\"I'll repay it.\"",
        truths: ("The owner never met {DL}.", "The real owner had emailed {DL} a signed letter authorizing the rental, later withdrawn."),
        defendant: [.direct("Did you take {V}'s money?", "\"I took it as the owner's agent. I believed I was authorized to collect the deposit and first month.\""), .direct("What authority did you have to rent it?", "\"I had a text message from the owner, and I believed that was enough. I was acting on it.\""), .direct("What happened with the owner?", "\"The owner backed out after the money came in. I did not expect that, and I was left holding it.\""), .direct("Please tell us about your arrangement with the owner.", "\"The owner and I agreed by text that I'd list the apartment and collect a deposit. I was to be paid a commission for each rental.\""), .direct("What did the owner send you?", "\"A short note authorizing me to rent the apartment for a stated price. I kept it on my phone and I showed it to {V}.\""), .direct("What happened to the money?", "\"I sent part of it to the owner and kept my commission. When the owner backed out, I was left with some of it and couldn't give it back right away.\""), .cross("You rented the same apartment to two renters, didn't you?", "\"It was a mix-up. I thought the first fell through. I did not mean to double book.\""), .cross("The lease was an online template, wasn't it?", "\"Yes. It was a standard form that I found online. Plenty of people use those.\""), .cross("Where is the $1,600 now?", "\"I do not have it all. I spent some of it, and I know that makes this look worse.\""), .cross("You rented the apartment to two people. How did that happen?", "\"A mix-up. The first renter didn't answer for two days, so I assumed the deal fell through and listed it again.\""), .cross("The photos came from another city. Why?", "\"I used photos the owner sent. I didn't know they were from somewhere else.\"")],
        openings: ("{V} paid {D} $1,600 as a deposit and first month's rent for an apartment listed online. The apartment belonged to someone else, and {D} had no authority to rent it.", "Listen for the defense evidence, which will show that {D} believed {D.he} was the owner's agent, acted on a text from the owner, and was left stranded when the owner backed out."),
        closings: ("A listing with photos from another city, a lease from an online template, and $1,600 paid to a person with no authority. The owner never met {D}.", "{D} acted on the owner's word, and the owner changed course. A deal that falls apart is not a fraud unless {D} meant to cheat from the start."),
        timeline: [(-12, "The listing goes up."), (-8, "{V} pays $1,600."), (0, "{V} finds the real owner at the door.")],
        identified: "The listing and payment record.",
        mood: .wantsConviction)

    static let neighborBoardPost = SmallCases.make(
        key: "story.neighborBoardPost",
        category: .publicOrder,
        headlines: ["Neighborhood Post Warns 'I Know Where You Park'", "Two Residents File Threat Complaints"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, a neighbor, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} saw a post on a neighborhood message board on {DATE} that read, 'I know where you park and I'll deal with you.' The account belonged to {D}, who had argued with {V} over a driveway. {DL} says the post was about a different person. {D} and {V} had argued over the driveway shortly before. The post, which does not name {V}, went up at about 8 p.m., and {V} read it an hour later.",
        state: [E(.digital, 3, "Post", "'I know where you park and I'll deal with you.'"), E(.document, 2, "Account Records", "The account is {D}'s.")],
